#!/usr/bin/env python3
import sys, os, re, math, json, csv, io, random, hashlib, time, datetime, calendar
from collections import OrderedDict
from decimal import Decimal, InvalidOperation

VERSION = "mlr 6.16.0"

# ---------------- Values ----------------
class AbsentType:
    pass
class MV:
    __slots__=("typ","val","orig")
    def __init__(self, typ, val=None, orig=None):
        self.typ=typ; self.val=val; self.orig=orig
    def __repr__(self):
        return f"MV({self.typ},{self.val!r},{self.orig!r})"
    def copy(self):
        return MV(self.typ, self.val, self.orig)

ABSENT = MV("absent", None)
ERROR = MV("error", None)
NULLMV = MV("null", None)
EMPTY = MV("empty", "")

def mv_int(v, orig=None): return MV("int", int(v), orig)
def mv_float(v, orig=None): return MV("float", float(v), orig)
def mv_str(v): return MV("string", str(v))
def mv_bool(v): return MV("bool", bool(v))
def mv_empty(): return MV("empty","")

INT_RE = re.compile(r'^[+-]?(?:0|[1-9][0-9]*|0[xX][0-9a-fA-F]+|0[oO][0-7]+|0[bB][01]+)$')
FLOAT_RE = re.compile(r'^[+-]?(?:(?:[0-9]+\.[0-9]*|\.[0-9]+|[0-9]+)(?:[eE][+-]?[0-9]+)|(?:[0-9]+\.[0-9]*|\.[0-9]+))$')

def parse_int_str(s):
    t=s.strip()
    neg=False
    if t and t[0] in '+-':
        neg = t[0]=='-'; t2=t[1:]
    else:
        t2=t
    try:
        if t2.lower().startswith('0x'): v=int(t2,16)
        elif t2.lower().startswith('0o'): v=int(t2,8)
        elif t2.lower().startswith('0b'): v=int(t2,2)
        else: v=int(t2,10)
    except Exception:
        return None
    return -v if neg else v

def infer(s, opts=None):
    if s=="":
        return mv_empty()
    if INT_RE.match(s):
        # leading-zero decimal like 001 already excluded by regex (except "0")
        v=parse_int_str(s)
        if v is not None:
            if opts and getattr(opts,'infer_int_as_float',False):
                try: return mv_float(float(v), s)
                except: pass
            return mv_int(v, s)
    if FLOAT_RE.match(s):
        # avoid float for plain integers handled above; requires dot/e in pattern - FLOAT_RE helps
        # plain "1e3" qualifies
        try:
            return mv_float(float(s), s)
        except: pass
    return mv_str(s)

def is_numeric(mv):
    return mv.typ in ("int","float")

def numeric_value(mv):
    """return (value, is_float) or None if not numeric-ish. absent/empty -> 0"""
    if mv.typ=="int": return (mv.val, False)
    if mv.typ=="float": return (mv.val, True)
    if mv.typ in ("absent","empty"): return (0, False)
    if mv.typ=="string":
        # strings that look numeric? Miller arithmetic on numeric strings gives error per probe ("3"*"4" error via literals typed string)
        return None
    return None

def format_float(v):
    if math.isnan(v): return "NaN"
    if math.isinf(v): return "+Inf" if v>0 else "-Inf"
    # Go FormatFloat 'f', -1 style: shortest decimal without exponent
    if v==0:
        return "0"
    # Use repr (shortest) then expand
    try:
        d=Decimal(repr(v))
    except Exception:
        return repr(v)
    s=format(d,'f')
    if '.' in s:
        s=s.rstrip('0').rstrip('.')
    return s

def apply_ofmt_to_float(v, opts):
    if opts is not None and getattr(opts,'ofmt',None):
        return sprintf(opts.ofmt, v)
    return None

def mv_to_string(mv, opts=None):
    """string representation used for output (dkvp etc) and string coercion"""
    if mv.typ=="absent": return "(absent)"
    if mv.typ=="error": return "(error)"
    if mv.typ=="empty": return ""
    if mv.typ=="string": return mv.val
    if mv.typ=="bool": return "true" if mv.val else "false"
    if mv.typ=="null": return "null"
    if mv.typ=="int":
        if opts is not None and getattr(opts,'ofmt',None) and getattr(opts,'ofmt_applies_to_int',False):
            pass
        return mv.orig if mv.orig is not None else str(mv.val)
    if mv.typ=="float":
        if opts is not None and getattr(opts,'ofmt',None):
            return sprintf(opts.ofmt, mv.val)
        return mv.orig if mv.orig is not None else format_float(mv.val)
    if mv.typ=="array":
        return json_stringify_mv(mv, opts)
    if mv.typ=="map":
        return json_stringify_mv(mv, opts)
    return str(mv.val)

def mv_to_json_value(mv, opts=None, quote_all=False):
    if mv.typ=="absent": return None
    if mv.typ=="error": return None
    if mv.typ=="empty": return "" if not quote_all else ""
    if mv.typ=="string": return mv.val
    if mv.typ=="bool": return mv.val
    if mv.typ=="null": return None
    if mv.typ=="int": return mv.val if not quote_all else mv_to_string(mv,opts)
    if mv.typ=="float": return mv.val if not quote_all else mv_to_string(mv,opts)
    if mv.typ=="array": return [mv_to_json_value(x,opts,quote_all) for x in mv.val]
    if mv.typ=="map": return OrderedDict((k, mv_to_json_value(v,opts,quote_all)) for k,v in mv.val.items())
    return mv.val

def json_escape_str(s):
    return json.dumps(s, ensure_ascii=False)

def json_stringify_mv(mv, opts=None, quote_all=False, compact=False):
    # Produce Miller JSON: numbers use mv_to_string, etc.
    if mv.typ=="array":
        inner=[json_stringify_mv(x,opts,quote_all,compact) for x in mv.val]
        if compact:
            return "["+", ".join(inner)+"]"
        else:
            return "["+", ".join(inner)+"]"
    if mv.typ=="map":
        parts=[]
        for k,v in mv.val.items():
            parts.append(json_escape_str(k)+": "+json_stringify_mv(v,opts,quote_all,compact))
        return "{"+", ".join(parts)+"}"
    if mv.typ=="string":
        return json_escape_str(mv.val)
    if mv.typ=="bool":
        return "true" if mv.val else "false"
    if mv.typ=="null":
        return "null"
    if mv.typ=="empty":
        return '""'
    if mv.typ=="error":
        return '"(error)"'
    if mv.typ=="absent":
        return "null"
    if mv.typ in ("int","float"):
        if quote_all:
            return json_escape_str(mv_to_string(mv,opts))
        return mv_to_string(mv,opts)
    return json_escape_str(str(mv.val))

def mv_truthy_for_filter(mv):
    # filter: boolean true passes; numeric non-zero? Miller filter expects bool; numbers?
    if mv.typ=="bool": return mv.val
    if mv.typ=="absent": return False
    if mv.typ=="error": return False
    if mv.typ=="empty": return False
    if mv.typ=="null": return False
    if mv.typ=="string": return len(mv.val)>0
    if mv.typ in ("int","float"): return mv.val!=0
    return bool(mv.val)

def mv_compare(a,b):
    """return -1,0,1 following Miller: numbers < strings etc, type ordering"""
    # absent handling caller
    def rank(m):
        if m.typ in ("int","float"): return 0
        if m.typ=="empty": return 1
        if m.typ=="string": return 2
        if m.typ=="bool": return 3
        if m.typ=="null": return 4
        if m.typ=="array": return 5
        if m.typ=="map": return 6
        if m.typ=="error": return 7
        return 8
    # numeric-string comparisons: Miller compares 1 == "1" true, and 1 < "a" ... numeric vs numeric-string?
    # If one numeric and other string that is numeric-inferable, compare numerically
    if a.typ in ("int","float") and b.typ=="string":
        inf=infer(b)
        if inf.typ in ("int","float"):
            av=float(a.val); bv=float(inf.val)
            return -1 if av<bv else (1 if av>bv else 0)
    if b.typ in ("int","float") and a.typ=="string":
        inf=infer(a)
        if inf.typ in ("int","float"):
            av=float(inf.val); bv=float(b.val)
            return -1 if av<bv else (1 if av>bv else 0)
    ra,rb=rank(a),rank(b)
    if a.typ in ("int","float") and b.typ in ("int","float"):
        av=float(a.val); bv=float(b.val)
        return -1 if av<bv else (1 if av>bv else 0)
    if ra!=rb:
        return -1 if ra<rb else 1
    # same rank
    if a.typ=="string" or a.typ=="empty":
        av=a.val if a.typ=="string" else ""; bv=b.val if b.typ=="string" else ""
        return -1 if av<bv else (1 if av>bv else 0)
    if a.typ=="bool":
        return -1 if (not a.val and b.val) else (1 if (a.val and not b.val) else 0)
    if a.typ=="null":
        return 0
    # arrays/maps compare by string
    av=mv_to_string(a); bv=mv_to_string(b)
    return -1 if av<bv else (1 if av>bv else 0)

def mv_equal(a,b):
    if a.typ=="absent" or b.typ=="absent":
        return a.typ==b.typ
    if a.typ in ("int","float") and b.typ in ("int","float"):
        return float(a.val)==float(b.val)
    # numeric vs string numeric
    if (a.typ in ("int","float") and b.typ=="string") or (b.typ in ("int","float") and a.typ=="string"):
        return mv_compare(a,b)==0
    if type(a)!=type(b):
        pass
    if a.typ!=b.typ:
        # empty vs string "" ?
        if set([a.typ,b.typ])==set(["empty","string"]):
            return (a.val or "")==(b.val or "")
        return False
    if a.typ=="array":
        return len(a.val)==len(b.val) and all(mv_equal(x,y) for x,y in zip(a.val,b.val))
    if a.typ=="map":
        if list(a.val.keys())!=list(b.val.keys()): return False
        return all(mv_equal(a.val[k],b.val[k]) for k in a.val)
    return a.val==b.val

# sprintf handling Go-style % formats used by fmtnum/format etc
def sprintf(fmt, *args):
    # Convert Go fmt style to Python %. Handle %d %f %e %g %s %x etc with ll etc.
    # Replace Go verbs: remove 'll','l' length modifiers, handle %v etc.
    # We'll process manually using Python % operator after sanitising.
    if fmt is None:
        return ""
    # Escape? fmt may contain %% 
    # Remove ll/l/h modifiers before verb letter
    f = re.sub(r'%(?P<flags>[-+ #0]?\d*(?:\.\d+)?)(?:ll|l|h)(?P<verb>[diouxXeEfFgGcs%])', r'%\g<flags>\g<verb>', fmt)
    # Go %v -> %s
    f = f.replace('%v','%s')
    # If args are MVs convert appropriately caller does.
    # Python % requires tuple
    try:
        # For %s ensure strings, etc. Python handles numbers too.
        return f % args if len(args)!=1 else f % args[0] if isinstance(args[0], tuple) else f % (args[0],) if "%" in f else f
    except Exception:
        # fallback simple
        try:
            return f % args
        except Exception:
            return f

def sprintf_mv(fmt_str, mv):
    # Determine verb type
    m=re.search(r'%[-+ #0\d\.]*(?:ll|l)?([diouxXeEfFgGcs])', fmt_str)
    if not m:
        # maybe %s etc
        return sprintf(fmt_str, mv_to_string(mv))
    verb=m.group(1)
    if verb in 'diouxX':
        if mv.typ in ("int",): v=mv.val
        elif mv.typ=="float": v=int(mv.val)
        elif mv.typ in ("empty","absent"): v=0
        elif mv.typ=="string":
            inf=infer(mv.val); v=inf.val if inf.typ in ("int","float") else 0
        else: v=0
        return sprintf(fmt_str, v)
    elif verb in 'eEfFgG':
        if mv.typ in ("int","float"): v=float(mv.val)
        elif mv.typ in ("empty","absent"): v=0.0
        elif mv.typ=="string":
            inf=infer(mv.val); v=float(inf.val) if inf.typ in ("int","float") else 0.0
        else: v=0.0
        return sprintf(fmt_str, v)
    else:
        return sprintf(fmt_str, mv_to_string(mv))

# ---------------- Records ----------------
class Record(OrderedDict):
    def __init__(self, *a, **kw):
        super().__init__(*a, **kw)
        self.meta={}
    def clone(self):
        r=Record()
        for k,v in self.items():
            r[k]=v
        r.meta=dict(self.meta)
        return r

def record_from_pairs(pairs, dedupe=True):
    rec=Record()
    counts={}
    for k,v in pairs:
        if dedupe:
            if k in rec:
                counts[k]=counts.get(k,1)+1
                nk=f"{k}_{counts[k]}"
                # ensure unique
                while nk in rec:
                    counts[k]+=1; nk=f"{k}_{counts[k]}"
                rec[nk]=v
            else:
                rec[k]=v
        else:
            rec[k]=v
    return rec

# Flatten / unflatten
def flatten_record(rec, sep=".", opts=None):
    out=Record(); out.meta=dict(rec.meta)
    for k,v in rec.items():
        flatten_into(out, k, v, sep)
    return out
def flatten_into(out, prefix, mv, sep):
    if mv.typ=="map":
        if len(mv.val)==0:
            out[prefix]=mv
        else:
            for kk,vv in mv.val.items():
                flatten_into(out, prefix+sep+kk, vv, sep)
    elif mv.typ=="array":
        if len(mv.val)==0:
            out[prefix]=mv
        else:
            for i,vv in enumerate(mv.val, start=1):
                flatten_into(out, prefix+sep+str(i), vv, sep)
    else:
        out[prefix]=mv

def unflatten_record(rec, sep=".", opts=None):
    # Build nested structure based on sep; numeric keys become arrays if consecutive 1..
    # Miller auto-unflatten: y.1,y.2 -> array
    root=OrderedDict()
    # We'll build via insertion into nested dicts represented as OrderedDict with special handling later converting numeric dicts to arrays
    def insert(parts, val):
        cur=root
        for p in parts[:-1]:
            if p not in cur or not isinstance(cur[p], OrderedDict):
                # if existing scalar, overwrite? keep as dict
                if p in cur and not isinstance(cur[p], OrderedDict):
                    cur[p]=OrderedDict()
                elif p not in cur:
                    cur[p]=OrderedDict()
            cur=cur[p]
        cur[parts[-1]]=val
    order=[]
    for k,v in rec.items():
        if sep in k:
            parts=k.split(sep)
            insert(parts, v)
        else:
            root[k]=v
    def convert(node):
        if isinstance(node, MV):
            return node
        if isinstance(node, OrderedDict):
            keys=list(node.keys())
            # check numeric 1..n
            if keys and all(k.isdigit() for k in keys):
                ints=sorted(int(k) for k in keys)
                if ints==list(range(1, len(keys)+1)):
                    arr=[convert(node[str(i)]) for i in ints]
                    return MV("array", arr)
            m=OrderedDict()
            for k,v in node.items():
                m[k]=convert(v)
            return MV("map", m)
        return node
    out=Record(); out.meta=dict(rec.meta)
    for k,v in root.items():
        if isinstance(v, MV):
            out[k]=v
        else:
            out[k]=convert(v)
    return out

PYEOF
"}

