            return p.stdout.decode('utf-8', errors='surrogateescape')
    # compressed by suffix or flags
    try:
        if opts.gzin or filename.endswith('.gz'):
            import gzip
            with gzip.open(filename,'rt',encoding='utf-8',errors='surrogateescape') as f: return f.read()
        if opts.bz2in or filename.endswith('.bz2'):
