            with lzma.open(filename,'rt',encoding='utf-8',errors='surrogateescape') as f: return f.read()
        if filename.endswith('.zip'):
            import zipfile
            z=zipfile.ZipFile(filename)
            names=z.namelist()
            if names: return z.read(names[0]).decode('utf-8',errors='surrogateescape')
        with open(filename,'r',encoding='utf-8',errors='surrogateescape',newline='') as f:
            return f.read()
    except FileNotFoundError:
