# ---------------- DSL ----------------
class DSLParseError(Exception): pass
class ReturnSignal(Exception):
    def __init__(self, val): self.val=val
class BreakSignal(Exception): pass
class ContinueSignal(Exception): pass

class Token:
    __slots__=("kind","text","line","col")
    def __init__(self,k,t,l=1,c=1): self.kind=k; self.text=t; self.line=l; self.col=c
    def __repr__(self): return f"<{self.kind}:{self.text}>"

DSL_KEYWORDS={"begin","end","if","elif","else","while","do","for","foreach","break","continue","func","subr","call","return","emit","emitf","emitp","print","fprint","unset","tee","dump","in","true","false","null","absent","filter"} # filter not

def lex_dsl(src):
    tokens=[]
    i=0; line=1; col=1
    n=len(src)
    def adv(k=1):
        nonlocal i,line,col
        for _ in range(k):
            if i<n and src[i]=="\n": line+=1; col=1
            else: col+=1
            i+=1
    while i<n:
        ch=src[i]
        if ch in " \t\r\n": adv(); continue
        if ch=="#" : # comment? DSL comments # or // ?
            # Miller DSL comments begin with # 
            while i<n and src[i]!="\n": adv()
            continue
        if ch=="/" and i+1<n and src[i+1]=="/":
            # could be // operator vs comment: if followed by space? Miller DSL uses # for comments, // is floor division operator in expressions. Ambiguous in statement start.
            # Treat // as operator token; comment handling only if at ... Heuristic: if previous token is operator/start and next char is ... Actually expressions like $x//2 no spaces.
            # We'll produce operator token.
            tokens.append(Token("op","//",line,col)); adv(2); continue
        start_line, start_col=line,col
        # String
        if ch=='"':
            j=i+1; raw=""
            while j<n:
                if src[j]=="\\" and j+1<n:
                    raw+=src[j:j+2]; j+=2; continue
                if src[j]=='"': break
                raw+=src[j]; j+=1
            # unescape keeping \1 etc as marker
            s=decode_dsl_string(raw)
            # consumed
            consumed=(j+1)-i
            # check suffix i for regex case-insensitive: "pattern"i  (immediately after quote, followed by non-alnum or space/comma/paren)
            ci=False
            if j+1<n and src[j+1]=='i' and (j+2>=n or not (src[j+2].isalnum() or src[j+2]=='_')):
                ci=True; consumed+=1
            # store token text as s, kind string, also ci attribute encoded?
            tok=Token("string_ci" if ci else "string", s, start_line, start_col)
            tokens.append(tok); adv(consumed); continue
        if ch=="'":
            # single-quoted string? Miller may allow? Treat as string
            j=i+1; raw=""
            while j<n and src[j]!="'":
                raw+=src[j]; j+=1
            tokens.append(Token("string", raw, start_line, start_col)); adv((j+1)-i if j<n else j-i); continue
        # Numbers
        if ch.isdigit() or (ch=="." and i+1<n and src[i+1].isdigit()):
            m=re.match(r'(?:0[xX][0-9a-fA-F]+|(?:\d+\.\d*|\.\d+|\d+)(?:[eE][+-]?\d+)?)', src[i:])
            if m:
                txt=m.group(0); tokens.append(Token("number", txt, start_line, start_col)); adv(len(txt)); continue
        # $ field / $* / ${} / $[[ ]]
        if ch=="$":
            # check patterns
            if src.startswith("$[[[", i):
                tokens.append(Token("op","$[[[",start_line,start_col)); adv(4); continue
            if src.startswith("$[[", i):
                tokens.append(Token("op","$[[",start_line,start_col)); adv(3); continue
            if src.startswith("$[", i):
                tokens.append(Token("op","$[",start_line,start_col)); adv(2); continue
            if src.startswith("$*", i):
                tokens.append(Token("full_srec","$*",start_line,start_col)); adv(2); continue
            if src.startswith("${", i):
                j=src.find("}", i+2)
                if j==-1: raise DSLParseError("unterminated ${}")
                name=src[i+2:j]
                tokens.append(Token("field_braced", name, start_line, start_col)); adv(j+1-i); continue
            # $name with dots segments
            m=re.match(r'\$([A-Za-z0-9_]+(?:\.[A-Za-z0-9_]+)*)', src[i:])
            if m:
                tokens.append(Token("field", m.group(1), start_line, start_col)); adv(len(m.group(0))); continue
            # lone $ ?
            tokens.append(Token("op","$",start_line,start_col)); adv(); continue
        if ch=="@":
            if src.startswith("@[[", i): # not sure
                tokens.append(Token("op","@[[",start_line,start_col)); adv(3); continue
            if src.startswith("@[", i):
                tokens.append(Token("op","@[",start_line,start_col)); adv(2); continue
            if src.startswith("@*", i):
                tokens.append(Token("full_oosvar","@*",start_line,start_col)); adv(2); continue
            if src.startswith("@{", i):
                j=src.find("}", i+2)
                if j==-1: raise DSLParseError("unterminated @{ }")
                tokens.append(Token("oosvar_braced", src[i+2:j], start_line, start_col)); adv(j+1-i); continue
            m=re.match(r'@([A-Za-z_][A-Za-z0-9_]*)', src[i:])
            if m:
                tokens.append(Token("oosvar", m.group(1), start_line, start_col)); adv(len(m.group(0))); continue
            tokens.append(Token("op","@",start_line,start_col)); adv(); continue
        # identifiers / keywords
        if ch.isalpha() or ch=="_":
            m=re.match(r'[A-Za-z_][A-Za-z0-9_]*', src[i:])
            txt=m.group(0); tokens.append(Token("ident", txt, start_line, start_col)); adv(len(txt)); continue
        # multi-char operators longest first
        multi=["**=",".//","**","<=>","!=~","=~","==","!=","<=",">=", "&&","||","<<",">>>",">>","//",".*","./",".%",".+",".-","??","+++","+=","-=","*=","/=","%=",".=","++","--","?:","[[[","[[","]]]","]","???" ]
        found=None
        for op in sorted(multi, key=len, reverse=True):
            if src.startswith(op,i):
                # ??? need token special: treat as op with text
                found=op; break
        if found:
            # special handling ??? length 3, ?? 2
            tokens.append(Token("op",found,start_line,start_col)); adv(len(found)); continue
        if ch in "(){}[];,?:.=<>+-*/%!~&|^":
            tokens.append(Token("op",ch,start_line,start_col)); adv(); continue
        # unknown char
        tokens.append(Token("unknown",ch,start_line,start_col)); adv()
    tokens.append(Token("eof","",line,col))
    return tokens

def decode_dsl_string(raw):
    out=""; i=0
    while i < len(raw):
        if raw[i]=="\\" and i+1 < len(raw):
            n=raw[i+1]
            if n=="n": out+="\n"
            elif n=="t": out+="\t"
            elif n=="r": out+="\r"
            elif n=="\\": out+="\\"
            elif n=='"': out+='"'
            elif n=="'": out+="'"
            elif n=="0": out+="\x00"
            elif n.isdigit():
                # capture reference: keep as \1 marker for later substitution (store char \x01+digit?)
                out+="\x01"+n
            elif n=="x" and i+3 < len(raw):
                try: out+=chr(int(raw[i+2:i+4],16)); i+=2
                except: out+=n
            else: out+=n
            i+=2
        else:
            out+=raw[i]; i+=1
    return out

# AST nodes are dicts with 'kind'
class Parser:
    def __init__(self, tokens, src=""):
        self.toks=tokens; self.pos=0; self.src=src
    def peek(self, offset=0):
        return self.toks[min(self.pos+offset, len(self.toks)-1)]
    def next(self):
        t=self.toks[self.pos]; self.pos+=1; return t
    def expect_op(self, op):
        t=self.peek()
        if t.kind=="op" and t.text==op:
            self.next(); return True
        raise DSLParseError(f'Parse error on token "{t.text}" at line {t.line} column {t.col}.')
    def match_op(self, op):
        t=self.peek()
        if t.kind=="op" and t.text==op:
            self.next(); return True
        return False
    def match_ident(self, word):
        t=self.peek()
        if t.kind=="ident" and t.text==word:
            self.next(); return True
        return False
    def parse_program(self):
        stmts=[]
        while self.peek().kind!="eof":
            if self.match_op(";"): continue
            stmts.append(self.parse_statement())
        return {"kind":"program","stmts":stmts}
    def parse_block_stmts_until(self, closing="}"):
        stmts=[]
        while not (self.peek().kind=="op" and self.peek().text==closing) and self.peek().kind!="eof":
            if self.match_op(";"): continue
            stmts.append(self.parse_statement())
        return stmts
    def parse_statement(self):
        t=self.peek()
        if t.kind=="ident":
            if t.text=="begin":
                self.next(); self.expect_op("{"); body=self.parse_block_stmts_until("}"); self.expect_op("}")
                return {"kind":"begin","body":body}
            if t.text=="end":
                self.next(); self.expect_op("{"); body=self.parse_block_stmts_until("}"); self.expect_op("}")
                return {"kind":"end","body":body}
            if t.text=="if":
                return self.parse_if()
            if t.text=="while":
                self.next(); self.expect_op("("); cond=self.parse_expr(); self.expect_op(")")
                body=self.parse_statement_or_block()
                return {"kind":"while","cond":cond,"body":body}
            if t.text=="do":
                self.next(); body=self.parse_statement_or_block()
                if not self.match_ident("while"): raise DSLParseError("expected while after do")
                self.expect_op("("); cond=self.parse_expr(); self.expect_op(")"); self.match_op(";")
                return {"kind":"dowhile","cond":cond,"body":body}
            if t.text=="for":
                return self.parse_for()
            if t.text=="foreach":
                # treat like for
                return self.parse_for()
            if t.text=="func" or t.text=="subr":
                is_func=t.text=="func"; self.next()
                name_tok=self.next()
                if name_tok.kind!="ident": raise DSLParseError("function name expected")
                self.expect_op("(")
                params=[]
                if not (self.peek().kind=="op" and self.peek().text==")"):
                    while True:
                        p=self.next(); params.append(p.text)
                        if not self.match_op(","): break
                self.expect_op(")"); self.expect_op("{"); body=self.parse_block_stmts_until("}"); self.expect_op("}")
                return {"kind":"funcdef","name":name_tok.text,"params":params,"body":body,"is_func":is_func}
            if t.text=="call":
                self.next(); expr=self.parse_expr(); self.match_op(";")
                return {"kind":"callstmt","expr":expr}
            if t.text=="return":
                self.next()
                if self.peek().kind=="op" and self.peek().text in (";","}"):
                    self.match_op(";"); return {"kind":"return","expr":None}
                if self.peek().kind=="eof":
                    return {"kind":"return","expr":None}
                expr=self.parse_expr(); self.match_op(";"); return {"kind":"return","expr":expr}
            if t.text=="break": self.next(); self.match_op(";"); return {"kind":"break"}
            if t.text=="continue": self.next(); self.match_op(";"); return {"kind":"continue"}
            if t.text in ("emit","emitf","emitp"):
                kind=t.text; self.next()
                # emit expr [, strings ...]  or emit {map} etc. emitf takes formats?
                args=[]
                # emit may have no arg? emit alone?
                if not (self.peek().kind=="op" and self.peek().text in (";","}")) and self.peek().kind!="eof":
                    args.append(self.parse_expr())
                    while self.match_op(","):
                        args.append(self.parse_expr())
                self.match_op(";")
                return {"kind":kind,"args":args}
            if t.text in ("print","fprint"):
                kind=t.text; self.next()
                args=[]
                redirect=None
                if not (self.peek().kind=="op" and self.peek().text in (";","}")) and self.peek().kind!="eof":
                    # print > "file", exprs ? Miller print with redirect as first?
                    args.append(self.parse_expr())
                    while self.match_op(","):
                        args.append(self.parse_expr())
                self.match_op(";")
                return {"kind":kind,"args":args}
            if t.text=="unset":
                self.next()
                # parse lvalue as expr primary with indices
                expr=self.parse_unary()
                self.match_op(";"); return {"kind":"unset","expr":expr}
            if t.text=="dump":
                self.next(); self.match_op(";"); return {"kind":"dump"}
            if t.text=="tee":
                self.next()
                args=[]
                if not (self.peek().kind=="op" and self.peek().text==";"):
                    args.append(self.parse_expr())
                    while self.match_op(","): args.append(self.parse_expr())
                self.match_op(";"); return {"kind":"teestmt","args":args}
        if t.kind=="op" and t.text=="{":
            self.next(); body=self.parse_block_stmts_until("}"); self.expect_op("}")
            return {"kind":"block","body":body}
        # expression statement
        expr=self.parse_expr()
        self.match_op(";")
        return {"kind":"exprstmt","expr":expr}
    def parse_statement_or_block(self):
        if self.peek().kind=="op" and self.peek().text=="{":
            self.next(); body=self.parse_block_stmts_until("}"); self.expect_op("}")
            return {"kind":"block","body":body}
        else:
            return self.parse_statement()
    def parse_if(self):
        self.match_ident("if"); self.expect_op("("); cond=self.parse_expr(); self.expect_op(")")
        then=self.parse_statement_or_block()
        else_branch=None
        if self.peek().kind=="ident" and self.peek().text=="elif":
            # convert elif to nested if
            self.next(); self.expect_op("("); c2=self.parse_expr(); self.expect_op(")"); b2=self.parse_statement_or_block()
            # check further elif/else chain manually: build nested
            nested={"kind":"if","cond":c2,"then":b2,"else":None}
            # parse trailing
            cur=nested
            while True:
                if self.peek().kind=="ident" and self.peek().text=="elif":
                    self.next(); self.expect_op("("); cc=self.parse_expr(); self.expect_op(")"); bb=self.parse_statement_or_block()
                    nn={"kind":"if","cond":cc,"then":bb,"else":None}; cur["else"]=nn; cur=nn; continue
                if self.peek().kind=="ident" and self.peek().text=="else":
                    self.next(); cur["else"]=self.parse_statement_or_block()
                break
            else_branch=nested
        elif self.peek().kind=="ident" and self.peek().text=="else":
            self.next(); else_branch=self.parse_statement_or_block()
        return {"kind":"if","cond":cond,"then":then,"else":else_branch}
    def parse_for(self):
        # for could be: for (init; cond; incr) body   or  for (k,v in expr) body or for (k in expr)
        self.next() # for/foreach
        self.expect_op("(")
        # Look ahead to find ' in ' at top level - scan tokens
        # Simpler try parse in-style: save pos, attempt parse a pattern ident/etc comma ... ident 'in'
        save=self.pos
        # Try in-style
        vars=[]
        # variables can be local ident, $field, @var ?
        # parse a var ref token sequence simple: if next tokens are ident (',' ident)* 'in'
        attempt=True
        temp_pos=self.pos
        var_names=[]
        while True:
            tok=self.peek()
            if tok.kind=="ident" and tok.text not in ("in",):
                var_names.append(tok.text); self.next()
            elif tok.kind in ("field","oosvar","full_srec"):
                var_names.append(tok.text); self.next()
            else:
                attempt=False; break
            if self.match_op(","): continue
            break
        if attempt and self.peek().kind=="ident" and self.peek().text=="in":
            self.next(); expr=self.parse_expr(); self.expect_op(")"); body=self.parse_statement_or_block()
            return {"kind":"forin","vars":var_names,"expr":expr,"body":body}
        # revert
        self.pos=save
        # C-style
        init=None
        if not (self.peek().kind=="op" and self.peek().text==";"):
            init=self.parse_expr()
        self.expect_op(";")
        cond=None
        if not (self.peek().kind=="op" and self.peek().text==";"):
            cond=self.parse_expr()
        self.expect_op(";")
        incr=None
        if not (self.peek().kind=="op" and self.peek().text==")"):
            incr=self.parse_expr()
        self.expect_op(")"); body=self.parse_statement_or_block()
        return {"kind":"for","init":init,"cond":cond,"incr":incr,"body":body}
    # Expression parsing with precedence
    def parse_expr(self):
        return self.parse_assign()
    def parse_assign(self):
        # check lvalue assignment
        left=self.parse_ternary()
        t=self.peek()
        if t.kind=="op" and t.text in ("=","+=","-=","*=","/=","%=","**=",".="):
            op=t.text; self.next(); right=self.parse_assign()
            return {"kind":"assign","op":op,"target":left,"value":right}
        return left
    def parse_ternary(self):
        expr=self.parse_coalesce()
        if self.peek().kind=="op" and self.peek().text=="?":
