            self.next(); true_e=self.parse_expr(); self.expect_op(":"); false_e=self.parse_ternary()
            return {"kind":"ternary","cond":expr,"then":true_e,"else":false_e}
        return expr
    def parse_coalesce(self):
        left=self.parse_or()
        while self.peek().kind=="op" and self.peek().text in ("??","???"):
            op=self.next().text; right=self.parse_or()
            left={"kind":"binary","op":op,"left":left,"right":right}
        return left
    def parse_or(self):
        left=self.parse_and()
        while self.peek().kind=="op" and self.peek().text=="||":
            self.next(); right=self.parse_and(); left={"kind":"binary","op":"||","left":left,"right":right}
        return left
    def parse_and(self):
