class TextOut:
    def __init__(self, text): self.text=text

class ExecEnv:
    def __init__(self, opts, processor):
        self.opts=opts; self.processor=processor
        self.record=None
        self.locals={}
        self.oos=processor.oos if processor else {}
        self.functions=processor.functions if processor else {}
        self.in_begin=False; self.in_end=False
        self.nr=0; self.fnr=0; self.filename="(stdin)"; self.filenum=1
        self.last_match=None # list groups or None
        self.last_value=ABSENT
        self.rand=random # global
    def get_field(self, name):
        if self.in_begin or self.in_end:
            raise MillerError("mlr: begin/end blocks cannot refer to records via $x, $*, etc")
        if self.record is None:
            raise MillerError("mlr: begin/end blocks cannot refer to records via $x, $*, etc")
        return get_field_from_record(self.record, name, self.opts)
    def set_field(self, name, val):
        if self.in_begin or self.in_end:
            raise MillerError("mlr: begin/end blocks cannot refer to records via $x, $*, etc")
        if self.record is None:
            raise MillerError("mlr: begin/end blocks cannot refer to records via $x, $*, etc")
        set_field_in_record(self.record, name, val, self.opts)
    def unset_field(self, name):
        if self.record is not None and name in self.record:
            del self.record[name]
        else:
            # dotted flat
            if self.record is not None and name in self.record: del self.record[name]

def get_field_from_record(rec, name, opts):
    # name may contain dots
    if name in rec:
        return rec[name]
    if "." in name:
        parts=name.split(".")
        if parts[0] in rec:
            cur=rec[parts[0]]
            for p in parts[1:]:
                if cur.typ=="map" and p in cur.val:
                    cur=cur.val[p]
                elif cur.typ=="array" and p.isdigit():
                    idx=int(p)-1
                    if 0 <= idx < len(cur.val): cur=cur.val[idx]
                    else: return ABSENT
                else:
                    return ABSENT
            return cur
    return ABSENT

def set_field_in_record(rec, name, val, opts):
    if val.typ=="absent":
        # assigning absent removes field
        if name in rec: del rec[name]
        return
    if "." in name:
        parts=name.split(".")
        # if base is map, set nested
        if parts[0] in rec and rec[parts[0]].typ=="map":
            cur=rec[parts[0]]
            for p in parts[1:-1]:
                if p not in cur.val or cur.val[p].typ!="map":
                    cur.val[p]=MV("map", OrderedDict())
                cur=cur.val[p]
            cur.val[parts[-1]]=val
            return
        rec[name]=val
        return
    rec[name]=val

def mv_from_python(v):
    if isinstance(v, MV): return v
    if isinstance(v, bool): return mv_bool(v)
    if v is None: return NULLMV
    if isinstance(v, int): return mv_int(v)
    if isinstance(v, float): return mv_float(v)
    if isinstance(v, str): return mv_str(v)
    if isinstance(v, list): return MV("array",[mv_from_python(x) for x in v])
    if isinstance(v, dict):
        m=OrderedDict()
        for k,val in v.items(): m[str(k)]=mv_from_python(val)
        return MV("map",m)
    return mv_str(str(v))

def python_from_mv(mv):
    if mv.typ=="array": return [python_from_mv(x) for x in mv.val]
    if mv.typ=="map": return {k:python_from_mv(v) for k,v in mv.val.items()}
    if mv.typ in ("int","float","string","bool"): return mv.val
    if mv.typ=="empty": return ""
    if mv.typ=="null": return None
    return None

# DSL execution
class DSLProcessor:
    def __init__(self, src, opts, is_filter=False, quiet=False, invert=False, seed_oos=None):
        self.src=src; self.opts=opts; self.is_filter=is_filter; self.quiet=quiet; self.invert=invert
        self.oos={}
        if seed_oos:
            for k,v in seed_oos.items(): self.oos[k]=v
        self.functions={}
        self.begin_bodies=[]; self.end_bodies=[]; self.main_stmts=[]
        try:
            toks=lex_dsl(src)
            prog=Parser(toks, src).parse_program()
        except DSLParseError as e:
            # Build Miller-like error message
            # Try extract token info from message
            raise MillerError(f"mlr: cannot parse DSL expression.\nmlr: {str(e)}\nPlease check for missing semicolon.\n")
        except MillerError:
            raise
        except Exception as e:
            raise MillerError(f"mlr: cannot parse DSL expression.\nmlr: {e}\n")
        for stmt in prog["stmts"]:
            if stmt["kind"]=="begin": self.begin_bodies.append(stmt["body"])
            elif stmt["kind"]=="end": self.end_bodies.append(stmt["body"])
            elif stmt["kind"]=="funcdef": self.functions[stmt["name"]]=(stmt["params"], stmt["body"], stmt["is_func"])
            else: self.main_stmts.append(stmt)
        # also funcdefs inside main? already registered top level only
        self.out_items=[]
        self.printed=[] # unused
    def make_env(self):
        return ExecEnv(self.opts, self)
    def run(self, records):
        self.out_items=[]
        # begin
        env=self.make_env(); env.in_begin=True
        for body in self.begin_bodies:
            self.exec_block(body, env)
        env.in_begin=False
        # main per record
        nr=0
        for rec in records:
            if isinstance(rec, TextOut):
                self.out_items.append(rec); continue
            nr+=1
            env=self.make_env()
            env.record=rec
            env.nr=rec.meta.get("nr", nr) if "nr" in rec.meta else nr
            env.fnr=rec.meta.get("fnr", nr)
            env.filename=rec.meta.get("filename","(stdin)")
            env.filenum=rec.meta.get("filenum",1)
            env.locals={}
            last=ABSENT
            for stmt in self.main_stmts:
                last=self.exec_stmt(stmt, env)
            env.last_value=last if last is not None else ABSENT
            if self.is_filter:
                cond=mv_truthy_for_filter(env.last_value) if isinstance(env.last_value, MV) else False
                if self.invert: cond=not cond
                if cond:
                    self.out_items.append(rec)
            else:
                if self.invert:
                    # put -x : prints records for which expression evaluates to false - main still modifies?
                    cond=mv_truthy_for_filter(env.last_value) if isinstance(env.last_value, MV) else False
                    if not cond and not self.quiet:
                        self.out_items.append(rec)
                elif not self.quiet:
                    self.out_items.append(rec)
        # end
        env=self.make_env(); env.in_end=True
        # end env needs reference to out_items ; exec emit will append
        # To allow NR in end? set nr to total
        env.nr=nr
        for body in self.end_bodies:
            self.exec_block(body, env)
        env.in_end=False
        return self.out_items
    def exec_block(self, stmts, env):
        last=ABSENT
        for s in stmts:
            last=self.exec_stmt(s, env)
        return last
    def exec_stmt(self, stmt, env):
        k=stmt["kind"]
        if k=="block": return self.exec_block(stmt["body"], env)
        if k=="begin": return self.exec_block(stmt["body"], env) # nested?
        if k=="end": return self.exec_block(stmt["body"], env)
        if k=="funcdef":
            self.functions[stmt["name"]]=(stmt["params"], stmt["body"], stmt["is_func"]); return ABSENT
        if k=="exprstmt":
            v=self.eval_expr(stmt["expr"], env); env.last_value=v; return v
        if k=="callstmt":
            v=self.eval_expr(stmt["expr"], env); return v
        if k=="if":
            cond=self.eval_expr(stmt["cond"], env)
            if mv_truthy_for_filter(cond):
                return self.exec_stmt(stmt["then"], env) if stmt["then"]["kind"]!="block" else self.exec_block(stmt["then"]["body"], env)
            elif stmt.get("else") is not None:
                e=stmt["else"]
                return self.exec_stmt(e, env) if e["kind"]!="block" else self.exec_block(e["body"], env)
            return ABSENT
        if k=="while":
            last=ABSENT
            while mv_truthy_for_filter(self.eval_expr(stmt["cond"], env)):
                try:
                    last=self.exec_stmt(stmt["body"], env) if stmt["body"]["kind"]!="block" else self.exec_block(stmt["body"]["body"], env)
                except BreakSignal: break
                except ContinueSignal: continue
            return last
        if k=="dowhile":
            last=ABSENT
            while True:
                try: last=self.exec_stmt(stmt["body"], env) if stmt["body"]["kind"]!="block" else self.exec_block(stmt["body"]["body"], env)
                except BreakSignal: break
                except ContinueSignal: pass
                if not mv_truthy_for_filter(self.eval_expr(stmt["cond"], env)): break
            return last
        if k=="for":
            if stmt["init"] is not None: self.eval_expr(stmt["init"], env)
            last=ABSENT
            while True:
                if stmt["cond"] is not None and not mv_truthy_for_filter(self.eval_expr(stmt["cond"], env)): break
                try: last=self.exec_stmt(stmt["body"], env) if stmt["body"]["kind"]!="block" else self.exec_block(stmt["body"]["body"], env)
                except BreakSignal: break
                except ContinueSignal: pass
                if stmt["incr"] is not None: self.eval_expr(stmt["incr"], env)
            return last
        if k=="forin":
            coll=self.eval_expr(stmt["expr"], env)
            last=ABSENT
            items=[]
            if coll.typ=="map":
                items=list(coll.val.items()) # key MV string, value
            elif coll.typ=="array":
                items=[(mv_int(i+1), v) for i,v in enumerate(coll.val)]
            elif coll.typ=="string":
                items=[(mv_int(i+1), mv_str(ch)) for i,ch in enumerate(coll.val)]
            else:
                items=[]
            vars=stmt["vars"]
            for key_mv, val_mv in items:
                if len(vars)==1:
                    # single var iterates values? Miller for (v in map) ??? or keys? Assume: if expr is $* (record) single var is key? Need heuristic: set var to value, if map also? We'll set to key if vars name like k... ambiguous. Set to value for array, key for map? Check common: for (k,v in $*) - two vars. Single var in array: value.
                    # Choose: map single -> key
                    if coll.typ=="map": self.assign_var_by_name(vars[0], key_mv, env)
                    else: self.assign_var_by_name(vars[0], val_mv, env)
                elif len(vars)>=2:
                    self.assign_var_by_name(vars[0], key_mv if isinstance(key_mv, MV) else mv_str(str(key_mv)), env)
                    self.assign_var_by_name(vars[1], val_mv, env)
                try: last=self.exec_stmt(stmt["body"], env) if stmt["body"]["kind"]!="block" else self.exec_block(stmt["body"]["body"], env)
                except BreakSignal: break
                except ContinueSignal: continue
            return last
        if k=="return":
            v=self.eval_expr(stmt["expr"], env) if stmt["expr"] is not None else ABSENT
            raise ReturnSignal(v)
        if k=="break": raise BreakSignal()
        if k=="continue": raise ContinueSignal()
        if k in ("emit","emitf","emitp"):
            self.do_emit(stmt, env, kind=k)
            return ABSENT
        if k in ("print","fprint"):
            vals=[self.eval_expr(a, env) for a in stmt["args"]]
            # fprint stderr? Miller fprint {stderr, "..."} ??? Simplistic: if first arg is identifier stderr? args evaluated would be local...
            txt=" ".join(mv_to_string(v, self.opts) for v in vals)
            if k=="fprint":
                sys.stderr.write(txt+"\n")
                self.out_items.append(TextOut("")) # no
                # remove last empty?
                self.out_items.pop()
            else:
                self.out_items.append(TextOut(txt+"\n"))
            return ABSENT
        if k=="unset":
            self.do_unset(stmt["expr"], env); return ABSENT
        if k=="dump":
            # print oos vars to stdout as records? Approx: emit all oos
            for name,val in env.oos.items():
                rec=Record(); rec[name]=val; self.out_items.append(rec)
            return ABSENT
        if k=="teestmt":
            # tee "filename", ??? Ignore / treat as print to file? DSL tee function usually call.
            return ABSENT
        return ABSENT
    def assign_var_by_name(self, name, val, env):
        if name.startswith("$"):
            env.set_field(name[1:], val)
        elif name.startswith("@"):
            env.oos[name[1:]]=val
        else:
            env.locals[name]=val
    def do_unset(self, node, env):
        if node["kind"]=="field":
            if env.record is not None and node["name"] in env.record: del env.record[node["name"]]
            elif env.record is not None:
                # dotted
                if "." in node["name"]:
                    parts=node["name"].split(".")
                    if parts[0] in env.record and env.record[parts[0]].typ=="map":
                        cur=env.record[parts[0]]
                        for p in parts[1:-1]:
                            if p in cur.val: cur=cur.val[p]
                        if parts[-1] in cur.val: del cur.val[parts[-1]]
        elif node["kind"]=="oosvar":
            env.oos.pop(node["name"], None)
        elif node["kind"]=="local":
            env.locals.pop(node["name"], None)
        elif node["kind"]=="full_srec":
            if env.record is not None: env.record.clear()
        elif node["kind"]=="index":
            target=node["target"]; idx=self.eval_expr(node["index"], env)
            key=mv_to_string(idx, self.opts)
            if target["kind"]=="field":
                fv=env.get_field(target["name"])
                if fv.typ=="map" and key in fv.val: del fv.val[key]
                elif env.record is not None and target["name"] in env.record: 
                    # if field is flat etc
                    pass
            elif target["kind"]=="oosvar":
                ov=env.oos.get(target["name"], ABSENT)
                if ov.typ=="map" and key in ov.val: del ov.val[key]
            elif target["kind"]=="full_srec":
                if env.record is not None and key in env.record: del env.record[key]
    def do_emit(self, stmt, env, kind="emit"):
        args_nodes=stmt["args"]
        if not args_nodes:
            # emit without args in end? emit current? no
            return
        if kind=="emitf":
            rec=Record()
            for node in args_nodes:
                v=self.eval_expr(node, env)
                name=self.name_for_emit(node, v)
                if v.typ=="absent": continue
                rec[name]=v
            self.out_items.append(rec); return
        # emit
        first_node=args_nodes[0]
        v=self.eval_expr(first_node, env)
        extra=[self.eval_expr(a, env) for a in args_nodes[1:]]
        extra_names=[mv_to_string(x, self.opts) for x in extra]
        if v.typ=="map":
            if not extra_names:
                rec=Record()
                for kk,vv in v.val.items(): rec[kk]=vv
                self.out_items.append(rec)
            else:
                # iterate recursively
                self.emit_map_recursive(v, extra_names, [], first_name=self.name_for_emit(first_node, v), out_prefix=[])
            return
        elif v.typ=="array":
            # emit array as records? each element if map
            for el in v.val:
                if el.typ=="map":
                    rec=Record()
                    for kk,vv in el.val.items(): rec[kk]=vv
                    self.out_items.append(rec)
                else:
                    rec=Record(); rec[self.name_for_emit(first_node,v)]=el; self.out_items.append(rec)
            return
        else:
            # scalar: field name from node
            if v.typ=="absent": return
            rec=Record(); rec[self.name_for_emit(first_node, v)]=v; self.out_items.append(rec); return
    def name_for_emit(self, node, v):
        if node["kind"]=="oosvar": return node["name"]
        if node["kind"]=="field": return node["name"]
        if node["kind"]=="local": return node["name"]
        if node["kind"]=="index":
            # @m[$k] etc fallback to base name
            return self.name_for_emit(node["target"], v)
        return "value"
    def emit_map_recursive(self, mvmap, key_names, key_vals, first_name, out_prefix):
        # key_names list remaining field names for levels
        if mvmap.typ!="map":
            rec=Record()
            for kn,kv in zip(reversed(key_names), reversed(key_vals)): # not
                pass
            # Build record: key fields in order of key_names corresponding to key_vals
            # key_vals accumulated in order
            for i,kn in enumerate(self._emit_key_names_cache):
                rec[kn]=key_vals[i]
            rec[first_name]=mvmap
            self.out_items.append(rec); return
        # store cache hack
        # We'll implement iterative via helper closure instead: use recursion with params in stack via attribute?
        # Simpler: use internal recursive function
        def rec_emit(cur, depth, acc):
            if cur.typ=="map" and depth < len(key_names):
                for kk,vv in cur.val.items():
                    rec_emit(vv, depth+1, acc+[mv_str(kk)])
            else:
                r=Record()
                for i,kn in enumerate(key_names):
                    if i < len(acc): r[kn]=acc[i]
                r[first_name]=cur
                self.out_items.append(r)
        rec_emit(mvmap,0,[])
    # Expression eval
    def eval_expr(self, node, env):
        k=node["kind"]
        if k=="literal":
            v=node["value"]
            if v.typ=="string" and "\x01" in v.val:
                # substitute capture groups
                s=v.val
                out=""; i=0
                groups=env.last_match or []
                while i < len(s):
                    if s[i]=="\x01" and i+1 < len(s) and s[i+1].isdigit():
                        idx=int(s[i+1])
                        if 1 <= idx <= len(groups): out+=groups[idx-1] or ""
                        i+=2
                    else: out+=s[i]; i+=1
                return mv_str(out)
            # return copy for mutable?
            return v
        if k=="field": return env.get_field(node["name"])
        if k=="full_srec":
            if env.in_begin or env.in_end: raise MillerError("mlr: begin/end blocks cannot refer to records via $x, $*, etc")
            m=OrderedDict()
            for kk,vv in env.record.items(): m[kk]=vv
            return MV("map", m)
        if k=="full_oosvar":
            m=OrderedDict()
            for kk,vv in env.oos.items(): m[kk]=vv
            return MV("map", m)
        if k=="oosvar": return env.oos.get(node["name"], ABSENT)
        if k=="local": return env.locals.get(node["name"], ABSENT)
        if k=="env":
            m=OrderedDict()
            for kk,vv in os.environ.items(): m[kk]=mv_str(vv)
            return MV("map", m)
        if k=="contextvar":
            name=node["name"]
            if name=="NR": return mv_int(env.nr)
            if name=="NF": return mv_int(len(env.record) if env.record is not None else 0)
            if name=="FNR": return mv_int(env.fnr)
            if name=="FILENAME": return mv_str(env.filename)
            if name=="FILENUM": return mv_int(env.filenum)
            if name=="FLATSEP": return mv_str(self.opts.flatsep)
            # IRS etc separators
            fs,ps,rs=effective_seps(self.opts, self.opts.informat, True)
            mapping={"IRS":rs,"IFS":fs,"IPS":ps,"ORS":self.opts.ors if self.opts._ors_explicit else "\n","OFS":effective_seps(self.opts,self.opts.outformat,False)[0],"OPS":effective_seps(self.opts,self.opts.outformat,False)[1]}
            return mv_str(mapping.get(name,""))
        if k=="array":
            return MV("array", [self.eval_expr(e, env) for e in node["elems"]])
        if k=="map":
            m=OrderedDict()
            for pair in node["pairs"]:
                if isinstance(pair[0], str):
                    key=pair[0]; v=self.eval_expr(pair[1], env)
                else:
                    kv=self.eval_expr(pair[0], env); key=mv_to_string(kv,self.opts); v=self.eval_expr(pair[1], env)
                if v.typ!="absent": m[key]=v
                else: m[key]=v
            return MV("map", m)
        if k=="index":
            target=self.eval_expr(node["target"], env)
            idx=self.eval_expr(node["index"], env)
            return index_mv(target, idx, self.opts)
        if k=="index2":
            target=self.eval_expr(node["target"], env)
            idx=self.eval_expr(node["index"], env)
            # [[ ]] is ?? For $*[[1]] maybe field name? For maps, [[ ]] returns key? Implement similar to index but if target map and idx int -> key name
            if target.typ=="map" and idx.typ=="int":
                keys=list(target.val.keys())
                if 1 <= idx.val <= len(keys): return mv_str(keys[idx.val-1])
                return ABSENT
            return index_mv(target, idx, self.opts)
        if k=="srec_index":
            idx=self.eval_expr(node["index"], env)
            key=mv_to_string(idx, self.opts)
            if env.record is None: raise MillerError("mlr: begin/end blocks cannot refer to records via $x, $*, etc")
            return env.record.get(key, ABSENT)
        if k=="srec_index2":
            idx=self.eval_expr(node["index"], env)
            if env.record is None: raise MillerError("mlr: begin/end blocks cannot refer to records via $x, $*, etc")
            if idx.typ=="int":
                keys=list(env.record.keys())
                if 1 <= idx.val <= len(keys): return mv_str(keys[idx.val-1])
                return ABSENT
            key=mv_to_string(idx, self.opts)
            return env.record.get(key, ABSENT)
        if k=="srec_index3":
            # $[[[ ]]] multi-key? treat as srec_index2
            idx=self.eval_expr(node["index"], env)
            return ABSENT
        if k=="oosvar_index":
            idx=self.eval_expr(node["index"], env)
            # @[key] ??? full oosvar map index
            key=mv_to_string(idx,self.opts)
            return env.oos.get(key, ABSENT)
        if k=="unary":
            v=self.eval_expr(node["expr"], env)
            return unary_op(node["op"], v, self.opts)
        if k=="postinc":
            # return old, increment target by 1
            old=self.eval_expr(node["expr"], env)
            delta=1 if node["op"]=="++" else -1
            nv=binary_op("+", old, mv_int(delta), self.opts)
            self.assign(node["expr"], nv, env)
            return old
        if k=="binary":
            return self.eval_binary(node, env)
        if k=="ternary":
            cond=self.eval_expr(node["cond"], env)
            if mv_truthy_for_filter(cond): return self.eval_expr(node["then"], env)
            else: return self.eval_expr(node["else"], env)
        if k=="assign":
            val=self.eval_expr(node["value"], env)
            if node["op"]!="=":
                # compound
                cur=self.eval_expr(node["target"], env)
                base_op=node["op"][:-1] # remove =
                # .= concat assignment : base_op is "."
                val=binary_op(base_op, cur, val, self.opts)
            self.assign(node["target"], val, env)
            return val
        if k=="call":
            args=[self.eval_expr(a, env) for a in node["args"]]
            # user functions first
            if node["name"] in self.functions:
                params, body, is_func=self.functions[node["name"]]
                return self.call_user(node["name"], params, body, is_func, args, env)
            return call_builtin(node["name"], args, env, self)
        raise MillerError(f"mlr: internal: unknown expr {k}")
    def eval_binary(self, node, env):
        op=node["op"]
        if op=="&&":
            left=self.eval_expr(node["left"], env)
            # Miller requires bool operands; if not bool returns error
            if left.typ!="bool": return ERROR
            if not left.val: return mv_bool(False)
            right=self.eval_expr(node["right"], env)
            if right.typ!="bool": return ERROR
            return mv_bool(right.val)
        if op=="||":
            left=self.eval_expr(node["left"], env)
            if left.typ!="bool": return ERROR
            if left.val: return mv_bool(True)
            right=self.eval_expr(node["right"], env)
            if right.typ!="bool": return ERROR
            return mv_bool(right.val)
        if op in ("??","???"):
            left=self.eval_expr(node["left"], env)
            if op=="??":
                if left.typ!="absent": return left
                return self.eval_expr(node["right"], env)
            else: # ??? absent or empty or null ? 
                if left.typ not in ("absent","empty","null"): return left
                return self.eval_expr(node["right"], env)
        left=self.eval_expr(node["left"], env)
        # for =~ need pattern info from right node (ci)
        right_node=node["right"]
        right=self.eval_expr(right_node, env)
        if op in ("=~","!=~"):
            # regex match
            if left.typ=="absent": return ABSENT
            pat=mv_to_string(right, self.opts)
            flags=re.IGNORECASE if right_node.get("ci") else 0
            # Node literal ci stored where? literal node may have ci at top level of node dict: check right_node (it is literal dict with ci)
            if isinstance(right_node, dict) and right_node.get("ci"): flags=re.IGNORECASE
            try:
                m=re.search(pat, mv_to_string(left,self.opts), flags)
            except re.error:
                return ERROR
            if m:
                env.last_match=list(m.groups())
            else:
                env.last_match=None
            result = m is not None
            if op=="!=~": result=not result
            return mv_bool(result)
        return binary_op(op, left, right, self.opts, env)
    def assign(self, target, val, env):
        k=target["kind"]
        if k=="field":
            env.set_field(target["name"], val); return
        if k=="oosvar":
            if val.typ=="absent":
                # assigning absent to oosvar? removes? Miller @var = absent ??? keep absent entry removal
                env.oos.pop(target["name"], None)
            else:
                env.oos[target["name"]]=val
            return
        if k=="local":
            env.locals[target["name"]]=val; return
        if k=="full_srec":
            if env.record is None: raise MillerError("mlr: begin/end blocks cannot refer to records via $x, $*, etc")
            env.record.clear()
            if val.typ=="map":
                for kk,vv in val.val.items(): env.record[kk]=vv
            elif val.typ=="absent":
                pass
            return
        if k=="full_oosvar":
            env.oos.clear()
            if val.typ=="map":
                for kk,vv in val.val.items(): env.oos[kk]=vv
            return
        if k=="srec_index":
            idx=self.eval_expr(target["index"], env); key=mv_to_string(idx,self.opts)
            if env.record is not None:
                if val.typ=="absent": env.record.pop(key,None)
                else: env.record[key]=val
            return
        if k=="index":
            # target target could be field/oos/local/full_srec/index chain
            base_node=target["target"]; idx=self.eval_expr(target["index"], env); key=mv_to_string(idx,self.opts)
            # Get container, modify, assign back if needed
            if base_node["kind"]=="field":
                cur=env.get_field(base_node["name"])
                new_cont=set_index_mv(cur, idx, val, self.opts)
                env.set_field(base_node["name"], new_cont); return
            if base_node["kind"]=="oosvar":
                cur=env.oos.get(base_node["name"], ABSENT)
                new_cont=set_index_mv(cur, idx, val, self.opts)
                env.oos[base_node["name"]]=new_cont; return
            if base_node["kind"]=="local":
                cur=env.locals.get(base_node["name"], ABSENT)
                new_cont=set_index_mv(cur, idx, val, self.opts)
                env.locals[base_node["name"]]=new_cont; return
            if base_node["kind"]=="full_srec":
                if env.record is not None:
                    if val.typ=="absent": env.record.pop(key,None)
                    else: env.record[key]=val
                return
            if base_node["kind"]=="index":
                # nested: evaluate container, set, assign back recursively
                cur=self.eval_expr(base_node, env)
                new_cont=set_index_mv(cur, idx, val, self.opts)
                # need to assign new_cont to base_node
                self.assign(base_node, new_cont, env); return
            if base_node["kind"]=="full_oosvar":
                new_cont=set_index_mv(MV("map", OrderedDict(env.oos)), idx, val, self.opts)
                env.oos.clear()
                if new_cont.typ=="map":
                    for kk,vv in new_cont.val.items(): env.oos[kk]=vv
                return
            # generic: evaluate and try mutate in place
            cur=self.eval_expr(base_node, env)
            new_cont=set_index_mv(cur, idx, val, self.opts)
            # cannot assign back -> ignore
            return
        if k=="env" or (k=="index"):
            return
        # other: ignore
    def call_user(self, name, params, body, is_func, args, env):
        # new env sharing oos, functions, record? func can access $ fields? Miller func can refer to $...? local functions are context-free? They can use params/locals only, but maybe also $?
        new_env=ExecEnv(self.opts, self)
        new_env.oos=env.oos; new_env.record=env.record; new_env.nr=env.nr; new_env.fnr=env.fnr; new_env.filename=env.filename; new_env.filenum=env.filenum
        new_env.locals={}
        for i,p in enumerate(params):
            new_env.locals[p]=args[i] if i < len(args) else ABSENT
        try:
            last=self.exec_block(body, new_env)
        except ReturnSignal as r:
            return r.val
        if is_func:
            return last if isinstance(last,MV) else ABSENT
        return ABSENT

def index_mv(target, idx, opts):
    if target.typ=="absent": return ABSENT
    if target.typ=="map":
        key=mv_to_string(idx, opts)
        return target.val.get(key, ABSENT)
    if target.typ=="array":
        if idx.typ in ("int","float"):
            i=int(idx.val)
            # 1-based
            if 1 <= i <= len(target.val): return target.val[i-1]
            if i<0 and abs(i) <= len(target.val): return target.val[i]
            return ABSENT
        return ABSENT
    if target.typ=="string":
