def binary_op(op, left, right, opts, env=None):
    # concat
    if op==".":
        if left.typ=="absent" or right.typ=="absent": 
            # concat with absent yields other? Empty?
            # Miller: absent . "a" ?
            ls="" if left.typ=="absent" else mv_to_string(left,opts)
            rs="" if right.typ=="absent" else mv_to_string(right,opts)
            return mv_str(ls+rs)
        if left.typ in ("array","map") or right.typ in ("array","map"): return ERROR
        return mv_str(mv_to_string(left,opts)+mv_to_string(right,opts))
    if op in ("==","!="):
        eq=mv_equal(left,right)
        return mv_bool(eq if op=="==" else not eq)
    if op in ("<","<=",">",">=","<=>"):
        if left.typ=="absent" or right.typ=="absent":
            # observed $missing <=> 1 gave absent (no field)
