            # If either is bool? earlier true<=>false gave 1 int, false<=>true -1. So bool fits numeric rank?
            # For empty vs null: c based rank empty(1) vs null(4) => -1 but observed true ... maybe they parsed as ("" <=> null) ??? Something else: maybe <=> returns ... Hmm return bool if one is null?
            # Keep int
            return mv_int(c)
    if op in ("&","|","^","<<",">>",">>>"):
        # bitwise requires int
        if left.typ in ("absent","empty"): li=0
        elif left.typ=="int": li=left.val
        elif left.typ=="float": li=int(left.val)
        else: return ERROR
        if right.typ in ("absent","empty"): ri=0
        elif right.typ=="int": ri=right.val
        elif right.typ=="float": ri=int(right.val)
        else: return ERROR
        if op=="&": return mv_int(li & ri)
        if op=="|": return mv_int(li | ri)
        if op=="^": return mv_int(li ^ ri)
        if op=="<<": return mv_int(li << ri)
        if op==">>": return mv_int(li >> ri)
        if op==">>>": return mv_int((li % (1<<64)) >> ri) # unsigned?
    # dot operators for collections: map/array elementwise
    base_op=op
    is_dot=False
    if op.startswith("."):
        is_dot=True; base_op=op[1:]
        if left.typ=="map" or right.typ=="map" or left.typ=="array" or right.typ=="array":
            # elementwise
            return dot_collection_op(base_op, left, right, opts)
        op=base_op
    if op in ("+","-","*","/","//","%","**","^^"):
        # numeric arithmetic
        # arrays/maps with + ??? [1,2]+[3] gave absent earlier - return ABSENT
        if left.typ in ("array","map") or right.typ in ("array","map"):
