                    # python rv 0 sign lost
                res=lv/rv
                # check int exact
                if not lf and not rf:
                    if lv % rv==0: return mv_int(lv//rv)
                    else: return mv_float(res)
                return mv_float(res)
            elif op=="//":
                if rv==0: return mv_float(float('inf'))
                res=math.floor(lv/rv) if (lf or rf) else lv//rv
                return mv_float(res) if (lf or rf) else mv_int(res)
            elif op=="%":
                if rv==0:
                    return mv_float(float('inf'))
                if lf or rf: res=math.fmod(lv,rv)
                else: res=lv % rv # Python mod sign follows divisor, Go % sign follows dividend. For negative need fix
                if not (lf or rf):
