    def get_field(self, name):
        if self.in_begin or self.in_end:
            raise MillerError("mlr: begin/end blocks cannot refer to records via $x, $*, etc")
        if self.record is None:
            raise MillerError("mlr: begin/end blocks cannot refer to records via $x, $*, etc")
        return get_field_from_record(self.record, name, self.opts)
    def set_field(self, name, val):
        if self.in_begin or self.in_end:
            raise MillerError("mlr: begin/end blocks cannot refer to records via $x, $*, etc")
        if self.record is None:
            raise MillerError("mlr: begin/end blocks cannot refer to records via $x, $*, etc")
        set_field_in_record(self.record, name, val, self.opts)
    def unset_field(self, name):
        if self.record is not None and name in self.record:
            del self.record[name]
        else:
            # dotted flat
            if self.record is not None and name in self.record: del self.record[name]

def get_field_from_record(rec, name, opts):
    # name may contain dots
    if name in rec:
        return rec[name]
    if "." in name:
        parts=name.split(".")
        if parts[0] in rec:
            cur=rec[parts[0]]
            for p in parts[1:]:
                if cur.typ=="map" and p in cur.val:
                    cur=cur.val[p]
                elif cur.typ=="array" and p.isdigit():
                    idx=int(p)-1
                    if 0 <= idx < len(cur.val): cur=cur.val[idx]
                    else: return ABSENT
                else:
                    return ABSENT
            return cur
    return ABSENT

def set_field_in_record(rec, name, val, opts):
    if val.typ=="absent":
        # assigning absent removes field
        if name in rec: del rec[name]
        return
    if "." in name:
        parts=name.split(".")
        # if base is map, set nested
        if parts[0] in rec and rec[parts[0]].typ=="map":
            cur=rec[parts[0]]
            for p in parts[1:-1]:
                if p not in cur.val or cur.val[p].typ!="map":
                    cur.val[p]=MV("map", OrderedDict())
                cur=cur.val[p]
            cur.val[parts[-1]]=val
            return
        rec[name]=val
        return
    rec[name]=val

def mv_from_python(v):
    if isinstance(v, MV): return v
    if isinstance(v, bool): return mv_bool(v)
    if v is None: return NULLMV
    if isinstance(v, int): return mv_int(v)
    if isinstance(v, float): return mv_float(v)
    if isinstance(v, str): return mv_str(v)
    if isinstance(v, list): return MV("array",[mv_from_python(x) for x in v])
    if isinstance(v, dict):
        m=OrderedDict()
        for k,val in v.items(): m[str(k)]=mv_from_python(val)
        return MV("map",m)
    return mv_str(str(v))

def python_from_mv(mv):
    if mv.typ=="array": return [python_from_mv(x) for x in mv.val]
    if mv.typ=="map": return {k:python_from_mv(v) for k,v in mv.val.items()}
    if mv.typ in ("int","float","string","bool"): return mv.val
    if mv.typ=="empty": return ""
    if mv.typ=="null": return None
    return None

