def expand_repl(repl, m):
    # repl contains \1 markers already converted to \\1 by caller? repl_py had \x01 -> "\\" so it's \1 string, re sub lambda needs interpret
    out=""; i=0
    while i < len(repl):
        if repl[i]=="\\" and i+1 < len(repl) and repl[i+1].isdigit():
            idx=int(repl[i+1])
            try: out+=m.group(idx) or ""
            except: pass
            i+=2
        else: out+=repl[i]; i+=1
    return out

