def expand_repl(repl, m):
    # repl contains \1 markers already converted to \\1 by caller? repl_py had \x01 -> "\\" so it's \1 string, re sub lambda needs interpret
    out=""; i=0
    while i < len(repl):
        if repl[i]=="\\" and i+1 < len(repl) and repl[i+1].isdigit():
            idx=int(repl[i+1])
            try: out+=m.group(idx) or ""
            except: pass
            i+=2
        else: out+=repl[i]; i+=1
    return out

def wrap_json_parsed(data):
    if isinstance(data, MV):
        if data.typ=="map":
            m=OrderedDict()
            for k,v in data.val.items(): m[k]=wrap_json_parsed(v)
            return MV("map",m)
        if data.typ=="array":
            return MV("array",[wrap_json_parsed(x) for x in data.val])
        return data
    if isinstance(data, bool): return mv_bool(data)
    if data is None: return NULLMV
    if isinstance(data, str): return mv_str(data)
    if isinstance(data, list): return MV("array",[wrap_json_parsed(x) for x in data])
    if isinstance(data, dict):
        m=OrderedDict()
        for k,v in data.items(): m[k]=wrap_json_parsed(v)
        return MV("map",m)
    return mv_from_python(data)
def mv_from_python_json(v):
    return wrap_json_parsed(v)

def stats_function(name, vals, rest, opts):
    # vals list of MV
    nums=[]; isfloat=False
    for v in vals:
        n,f=num_arg(v)
        if n is not None: nums.append(n); isfloat=isfloat or f
    if name=="mean":
        if not nums: return ABSENT
        return mv_float(sum(nums)/len(nums))
    if name in ("variance","stddev"):
        if len(nums)<2: return mv_float(0) if nums else ABSENT
        m=sum(nums)/len(nums); var=sum((x-m)**2 for x in nums)/(len(nums)-1)
        return mv_float(var if name=="variance" else math.sqrt(var))
    if name=="median":
        if not nums: return ABSENT
        ss=sorted(nums); mid=len(ss)//2
        return mv_float(ss[mid] if len(ss)%2==1 else (ss[mid-1]+ss[mid])/2)
    if name=="mode" or name=="antimode":
        counts={}
        order=[]
        for v in vals:
            key=mv_to_string(v,opts)
            if key not in counts: counts[key]=(0,v); order.append(key)
            counts[key]=(counts[key][0]+1, v)
        if not order: return ABSENT
        if name=="mode": best=max(order, key=lambda k: counts[k][0])
        else: best=min(order, key=lambda k: counts[k][0])
        return counts[best][1]
    if name=="minlen": return mv_int(min([len(mv_to_string(v,opts)) for v in vals], default=0))
    if name=="maxlen": return mv_int(max([len(mv_to_string(v,opts)) for v in vals], default=0))
    if name=="distinct_count":
        return mv_int(len(set(mv_to_string(v,opts) for v in vals)))
    if name=="null_count":
        return mv_int(sum(1 for v in vals if v.typ in ("empty","null")))
    if name=="sum2": return mv_float(sum(x*x for x in nums))
    if name=="sum3": return mv_float(sum(x**3 for x in nums))
    if name=="sum4": return mv_float(sum(x**4 for x in nums))
    if name=="madd":
        if not nums: return ABSENT
        m=sum(nums)/len(nums); return mv_float(sum(abs(x-m) for x in nums)/len(nums))
    if name=="meaneb":
        if len(nums)<2: return mv_float(0)
        m=sum(nums)/len(nums); var=sum((x-m)**2 for x in nums)/(len(nums)-1); return mv_float(math.sqrt(var/len(nums)))
    if name=="skewness" or name=="kurtosis":
        if len(nums)<3: return mv_float(0)
        m=sum(nums)/len(nums); var=sum((x-m)**2 for x in nums)/(len(nums)-1); sd=math.sqrt(var) if var else 0
        if sd==0: return mv_float(0)
        if name=="skewness":
            # sample skewness Miller formula approximation
            n=len(nums); return mv_float(n/((n-1)*(n-2))*sum(((x-m)/sd)**3 for x in nums))
        else:
            n=len(nums)
            # excess kurtosis sample
