def parse_regex_spec(s):
    # Miller regex spec may be "pattern"i  or "pattern" quoted
    ci=False
    if len(s)>=2 and s[0]=='"' :
        # find closing quote
        # pattern is quoted, optional i after
        # e.g. '"sda[0-9]"i' - shell would have removed outer single, content is "sda[0-9]"i
        if s.endswith('"i') or s.endswith('i') and '"' in s[1:]:
            # parse
            end=s.rfind('"')
            if end>0:
                ci=s[end+1:]=="i"
                return s[1:end], ci
        if s.endswith('"'):
            return s[1:-1], False
    return s, ci

def verb_rename(records,args,opts,ctx):
    spec={"-r":("r",False,False),"-g":("g",False,False)}
    o,pos=parse_verb_args("rename",args,spec)
    if not pos: raise VerbUsageError("rename")
    parts=pos[0].split(",") if len(pos)==1 else []
    if len(pos)>1:
        # maybe comma-less? Miller requires comma list as single arg
        parts=[]
        for p in pos: parts.extend(p.split(","))
    if len(parts)%2!=0: raise MillerError("mlr: mlr rename: old/new field names must be paired")
    pairs=[(parts[i],parts[i+1]) for i in range(0,len(parts),2)]
    regex=bool_opt(o,"r"); glob=bool_opt(o,"g")
    out=[]
    for r in records:
        if isinstance(r,TextOut): out.append(r); continue
        new=Record(); new.meta=dict(r.meta)
        for k,v in r.items():
            nk=k
            for old,newname in pairs:
                if regex:
                    pat,ci=parse_regex_spec(old)
                    flags=re.IGNORECASE if ci else 0
                    m=re.search(pat,k,flags)
                    if m:
                        if glob:
                            def repl(mm):
                                s=newname
                                for gi in range(1,10):
                                    s=s.replace(f"\\{gi}", mm.group(gi) if gi <= len(mm.groups()) and mm.group(gi) else "")
                                return s
                            nk=re.sub(pat, repl, k, flags=flags)
                        else:
                            # replace matched portion with newname expanded
                            expanded=newname
                            for gi in range(1,10):
                                expanded=expanded.replace(f"\\{gi}", m.group(gi) if gi <= len(m.groups()) and m.group(gi) else "")
                            nk=k[:m.start()]+expanded+k[m.end():]
                        break
                else:
                    if k==old: nk=newname; break
            new[nk]=v
        out.append(new)
    return out

