# ---------------- Verbs ----------------
class VerbHelp(Exception):
    def __init__(self, verb): self.verb=verb
class VerbUsageError(Exception):
    def __init__(self, verb, msg=None): self.verb=verb; self.msg=msg

def split_names(s):
    if s is None or s=="": return []
    if s=="": return [""]
    return s.split(",")

def parse_verb_args(verb, args, spec):
    """spec dict flag->(dest, takes_value, multiple)
    returns (opts dict, positionals list)
    spec also may include '--flag=value' handling
    """
    opts={}
    pos=[]
    i=0
    # defaults
    for flag,(dest,takes,multiple) in spec.items():
        if multiple: opts[dest]=[]
    def store(dest, val, multiple):
        if multiple:
            opts.setdefault(dest, []).append(val)
        else:
            opts[dest]=val
    while i < len(args):
        a=args[i]
        if a in ("-h","--help"):
            raise VerbHelp(verb)
        # --flag=value
        if a.startswith("--") and "=" in a:
            flag,val=a.split("=",1)
            if flag in spec:
                dest,takes,multiple=spec[flag]
                if not takes: raise MillerError(f'mlr: mlr {verb}: option "{flag}" not recognized')
                store(dest,val,multiple); i+=1; continue
        if a in spec:
            dest,takes,multiple=spec[a]
            if takes:
                if i+1>=len(args):
                    # usage error
                    raise VerbUsageError(verb, f'mlr: mlr {verb}: option "{a}" requires an argument')
                store(dest,args[i+1],multiple); i+=2; continue
            else:
                store(dest,True,multiple); i+=1; continue
