def parse_regex_spec(s):
    # Miller regex spec may be "pattern"i  or "pattern" quoted
    ci=False
    if len(s)>=2 and s[0]=='"' :
        # find closing quote
        # pattern is quoted, optional i after
        # e.g. '"sda[0-9]"i' - shell would have removed outer single, content is "sda[0-9]"i
        if s.endswith('"i') or s.endswith('i') and '"' in s[1:]:
