        if a.startswith("-") and not a.startswith("--") and len(a)>2 and all(("-"+ch) in spec and not spec["-"+ch][1] for ch in a[1:]):
            for ch in a[1:]:
                dest,takes,multiple=spec["-"+ch]
                store(dest,True,multiple)
            i+=1; continue
        if a.startswith("-") and a!="-":
            raise MillerError(f'mlr: mlr {verb}: option "{a}" not recognized')
