def opts_names(opts, dest):
    v=opts.get(dest, [])
    names=[]
    if isinstance(v, list):
        for item in v: names.extend(split_names(item))
    elif v is not None:
        names=split_names(v)
    return names

def bool_opt(opts,dest): return bool(opts.get(dest,False))

def group_key(rec, fields, opts):
    return tuple(mv_to_string(rec[f],opts) if f in rec else "" for f in fields)

def groups_in_order(records, fields, opts):
    groups=OrderedDict()
    for r in records:
        k=group_key(r,fields,opts)
        groups.setdefault(k, []).append(r)
    return groups

def make_record_from_group(fields, key_vals, opts):
    rec=Record()
    for f,v in zip(fields, key_vals):
        rec[f]=infer(v,opts) if v!="" else mv_empty()
        # But group values originally MV: better keep original type. Caller should use MV list.
    return rec

def group_record(fields, key_mvs):
    rec=Record()
    for f,v in zip(fields, key_mvs):
        rec[f]=v
    return rec

def key_mvs(rec, fields):
    return [rec[f] if f in rec else mv_empty() for f in fields]

# Statistics accumulator computation
def compute_stat(acc, values, opts, interpolated=False):
    # values list MV
    if acc=="count":
        return mv_int(len(values))
    if acc=="null_count":
        return mv_int(sum(1 for v in values if v.typ in ("empty","null")))
    if acc=="distinct_count":
        return mv_int(len(set(mv_to_string(v,opts) for v in values)))
    if acc=="mode" or acc=="antimode":
        counts=OrderedDict()
        for v in values:
            k=(v.typ, mv_to_string(v,opts))
            if k not in counts: counts[k]=[0,v]
            counts[k][0]+=1
        if not counts: return ABSENT
        if acc=="mode":
            best=max(counts.values(), key=lambda x: x[0])
        else:
            best=min(counts.values(), key=lambda x: x[0])
        return best[1]
    if acc=="minlen":
        return mv_int(min([len(mv_to_string(v,opts)) for v in values], default=0))
    if acc=="maxlen":
        return mv_int(max([len(mv_to_string(v,opts)) for v in values], default=0))
    if acc=="min":
        if not values: return ABSENT
        best=values[0]
        for v in values[1:]:
            if mv_compare(v,best)<0: best=v
        return best
    if acc=="max":
        if not values: return ABSENT
        best=values[0]
        for v in values[1:]:
            if mv_compare(v,best)>0: best=v
        return best
    # numeric accumulators
    nums=[]
    all_int=True
    for v in values:
        if v.typ=="int": nums.append(float(v.val))
        elif v.typ=="float": nums.append(v.val); all_int=False
        elif v.typ in ("empty","null","absent"): continue
        else:
            # string numeric? Miller requires numeric; skip? For mean of strings would be ??? Return empty?
            inf=infer(v.val) if v.typ=="string" else None
            if inf and inf.typ in ("int","float"): nums.append(float(inf.val))
            else: continue
    if acc=="sum":
        if not nums: return mv_int(0)
        s=sum(nums)
        return mv_int(int(s)) if all_int else mv_float(s)
    if not nums:
        return mv_empty()
    if acc=="mean":
        return mv_float(sum(nums)/len(nums))
    if acc=="mad":
        m=sum(nums)/len(nums)
        return mv_float(sum(abs(x-m) for x in nums)/len(nums))
    if acc in ("var","stddev","meaneb"):
        if len(nums)<2:
            # Miller var for single? likely 0? Probe later
            var=0.0
        else:
            m=sum(nums)/len(nums); var=sum((x-m)**2 for x in nums)/(len(nums)-1)
        if acc=="var": return mv_float(var)
        if acc=="stddev": return mv_float(math.sqrt(var))
        if acc=="meaneb": return mv_float(math.sqrt(var/len(nums)) if nums else 0.0)
    if acc=="skewness" or acc=="kurtosis":
        if len(nums)<3: return mv_float(0.0)
        m=sum(nums)/len(nums)
        if len(nums)<2: return mv_float(0.0)
        var=sum((x-m)**2 for x in nums)/(len(nums)-1); sd=math.sqrt(var) if var>0 else 0.0
        if sd==0: return mv_float(0.0)
        n=len(nums)
        if acc=="skewness":
            return mv_float(n/((n-1)*(n-2))*sum(((x-m)/sd)**3 for x in nums))
        else:
            s4=sum(((x-m)/sd)**4 for x in nums)
            if n<4: return mv_float(0.0)
            return mv_float((n*(n+1)/((n-1)*(n-2)*(n-3)))*s4 - 3*(n-1)**2/((n-2)*(n-3)))
    if acc.startswith("p") or acc=="median":
        pval=50.0 if acc=="median" else float(acc[1:])
        # sorted values: if numeric nums else string values
        # Determine if all numeric
        if len(nums)==len([v for v in values if v.typ in ("int","float")]) and nums:
            ss=sorted(nums)
            if interpolated:
                # type7
                if len(ss)==1: return mv_float(ss[0])
                h=(len(ss)-1)*(pval/100); lo=math.floor(h); hi=math.ceil(h)
                if lo==hi: return mv_float(ss[int(h)])
                return mv_float(ss[lo]+(ss[hi]-ss[lo])*(h-lo))
            else:
                idx=math.ceil(pval/100*len(ss))-1
                idx=max(0,min(len(ss)-1,idx))
                v=ss[idx]
                # return type matching original? If ints and integral, int
                # keep float if any float else int
                return mv_float(v) if not all_int else mv_int(int(v))
        else:
            # string percentile: sort MVs
            ss=sorted(values, key=lambda v: mv_to_string(v,opts))
            idx=math.ceil(pval/100*len(ss))-1
            idx=max(0,min(len(ss)-1,idx))
            return ss[idx]
    return ABSENT

