    for r in records:
        if isinstance(r,TextOut): out.append(r); continue
        # determine target groups: if collapse substrings, group fields by name with substrings removed
        nr=Record(); nr.meta=dict(r.meta)
        # collect field groups
        groups=OrderedDict() # out_field_name -> (input fields, values)
        if collapse:
            for k,v in r.items():
                base=k
                for sub in collapse: base=base.replace(sub,"")
                groups.setdefault(base, []).append(v)
            # output fields ??? help example needed. Output name would be base_acc ?
            # Implementation: for each base group, compute stats, output field f"{base}_{acc}", optionally keep originals if -k
            if bool_opt(o,"k"):
                for k,v in r.items(): nr[k]=v
            for base, vals in groups.items():
