                    v=compute_stat(acc, vals, opts, bool_opt(o,"i"))
                    if v.typ!="absent": nr[f"{base}_{acc}"]=v
            out.append(nr); continue
        target_fields=fields[:]
        if regex_fields:
            # regex_fields are patterns, not names
            for pat in regex_fields:
                p,ci=parse_regex_spec(pat)
                for k in r.keys():
                    if re.search(p,k,re.IGNORECASE if ci else 0) and k not in target_fields: target_fields.append(k)
        vals=[r[f] for f in target_fields if f in r]
        if bool_opt(o,"k") or not outname:
            for k,v in r.items(): nr[k]=v
        else:
            for k,v in r.items():
                if k not in target_fields: nr[k]=v
