def execute_verb(verb, records, args, opts, ctx):
    # Separate TextOut for most verbs
    if verb in ("put","filter"):
        return execute_dsl_verb(verb, records, args, opts, ctx)
    texts=[r for r in records if isinstance(r, TextOut)]
    recs=[r for r in records if not isinstance(r, TextOut)]
    func=VERB_FUNCS.get(verb)
    if func is None:
        raise MillerError(f'mlr: verb "{verb}" not found. Please use "mlr -l" for a list.')
    out=func(recs, args, opts, ctx)
    # For verbs that are terminal file verbs etc, texts handling..
    if texts:
        # print texts before output records
        return texts+out
    return out

def execute_dsl_verb(verb, records, args, opts, ctx):
    # parse DSL verb args
    expr_parts=[]; files_dsl=[]; seed_oos={}; quiet=False; invert=False
    ast_flags=[]
    i=0
    while i < len(args):
        a=args[i]
        if a in ("-h","--help"): raise VerbHelp(verb)
        elif a=="-f":
            if i+1>=len(args): raise MillerError(f"mlr: mlr {verb}: -f requires argument")
            fn=args[i+1]
            if os.path.isdir(fn):
                for name in sorted(os.listdir(fn)):
                    if name.endswith(".mlr"):
                        with open(os.path.join(fn,name)) as fh: expr_parts.append(fh.read())
            else:
                try:
                    with open(fn) as fh: expr_parts.append(fh.read())
                except FileNotFoundError:
                    raise MillerError(f"mlr: open {fn}: no such file or directory")
            i+=2; continue
        elif a=="-e":
            if i+1>=len(args): raise MillerError(f"mlr: mlr {verb}: -e requires argument")
            expr_parts.append(args[i+1]); i+=2; continue
        elif a=="-s":
            if i+1>=len(args): raise MillerError("mlr: mlr put: -s requires argument")
            kv=args[i+1]
            if "=" in kv:
                k,v=kv.split("=",1); seed_oos[k]=infer(v,opts)
            i+=2; continue
        elif a=="-q": quiet=True; i+=1; continue
        elif a=="-x": invert=True; i+=1; continue
        elif a in ("-S","-F","-w","-W"): i+=1; continue
        elif a in ("-p","-d","-D","-E","-v","-X"): ast_flags.append(a); i+=1; continue
        elif a.startswith("-") and a!="-":
            raise MillerError(f'mlr: mlr {verb}: option "{a}" not recognized')
        else:
            expr_parts.append(a); i+=1; continue
    src="; ".join(expr_parts) if len(expr_parts)>1 and False else "".join([p if p.endswith((";","}","\n")) or idx==len(expr_parts)-1 else p+";" for idx,p in enumerate(expr_parts)]) if expr_parts else ""
    # If single positional expr, src is exactly it
    if len(expr_parts)==1: src=expr_parts[0]
    # Load global --load files? opts load_files contain DSL definitions
    if opts.load_files:
        pre=[]
        for fn in opts.load_files:
            try:
                with open(fn) as fh: pre.append(fh.read())
            except: pass
        src=";".join(pre+[src]) if src else ";".join(pre)
    if ast_flags:
        # Miller parser info: print AST approximated. Tests unlikely complex. If -X or -p etc, we output using our txt repr and return no records if -X else continue?
        # For -v = -E -p : echo expression then AST
        out_text=""
        if "-E" in ast_flags or "-v" in ast_flags: out_text+=src+"\n"
        # Simple AST dump: use token list
        try:
            toks=lex_dsl(src); prog=Parser(toks,src).parse_program(); ast_repr=repr(prog)
        except Exception as e: ast_repr=str(e)
        out_text+=ast_repr+"\n"
        sys.stdout.write(out_text)
        if "-X" in ast_flags or "-p" in ast_flags or "-d" in ast_flags or "-D" in ast_flags or "-v" in ast_flags:
            # Miller with -p prints AST to stdout and still processes? -X exits after parsing. -p alone maybe prints AST and processes? Need guess: Return [] to avoid duplicate? We'll if -X only AST, else AST plus processing would double... treat all as AST only.
            return []
    proc=DSLProcessor(src, opts, is_filter=(verb=="filter"), quiet=quiet, invert=invert, seed_oos=seed_oos)
    return proc.run(records)

