USAGE_MAIN="""Usage: mlr [flags] {verb} [verb-dependent options ...] {zero or more file names}

If zero file names are provided, standard input is read, e.g.
  mlr --csv sort -f shape example.csv

Output of one verb may be chained as input to another using "then", e.g.
  mlr --csv stats1 -a min,mean,max -f quantity then sort -f color example.csv

Please see 'mlr help topics' for more information.
Please also see https://miller.readthedocs.io
"""

def get_help_text(kind, name):
    if help_data is not None:
        if kind=="verb" and name in help_data.VERB_HELP: return help_data.VERB_HELP[name]
        if kind=="function" and name in getattr(help_data,"FUNCTION_HELP",{}): return help_data.FUNCTION_HELP[name]
        if kind=="keyword" and name in getattr(help_data,"KEYWORD_HELP",{}): return help_data.KEYWORD_HELP[name]
        if kind=="topic" and name in getattr(help_data,"TOPIC_HELP",{}): return help_data.TOPIC_HELP[name]
        if kind=="flag" and name in getattr(help_data,"FLAG_HELP",{}): return help_data.FLAG_HELP.get(name)
    return None

def handle_help_args(args):
    # args after 'help' or help shorthands handled in main
    # returns exit code
    if not args:
        sys.stdout.write(USAGE_MAIN); return 0
    # help topics etc combined
    # Forms: help {topic}, help verb {name}, help function {name}, help keyword {name}, help flag {name}, help list-verbs etc, help find ...
    if help_data is not None and hasattr(help_data,"HELP_MAP"):
        key=" ".join(args)
        if key in help_data.HELP_MAP:
            sys.stdout.write(help_data.HELP_MAP[key]); return 0
    first=args[0]
    if first=="topics":
        txt=get_help_text("topic","topics")
        if txt: sys.stdout.write(txt); return 0
    if first in ("verb","verbs") and len(args)>=2:
        name=args[1]
        if name not in ALL_VERBS and name not in PROBED_VERB_ORDER:
            sys.stdout.write(f'mlr: verb "{name}" not found. Please use "mlr help list-verbs" for a list.\n'); return 0
        txt=get_help_text("verb",name)
        if txt: sys.stdout.write(txt); return 0
    if first in ("function","functions") and len(args)>=2:
        name=args[1]
        txt=get_help_text("function",name)
        if txt: sys.stdout.write(txt); return 0
        sys.stdout.write(f'No help found for "{name}".\n'); return 0
    if first in ("keyword","keywords") and len(args)>=2:
        name=args[1]
        txt=get_help_text("keyword",name)
        if txt: sys.stdout.write(txt); return 0
    if first in ("flag","flags"):
        if len(args)>=2:
            name=args[1]
            txt=None
            if help_data and hasattr(help_data,"FLAG_HELP"):
                txt=help_data.FLAG_HELP.get(name) or help_data.FLAG_HELP.get("--"+name.lstrip("-"))
            if txt: sys.stdout.write(txt if txt.endswith("\n") else txt+"\n"); return 0
        else:
            txt=get_help_text("topic","flags")
            if txt: sys.stdout.write(txt); return 0
    if first=="list-verbs":
        for v in PROBED_VERB_ORDER: sys.stdout.write(v+"\n")
        return 0
    if first=="usage-verbs":
        if help_data and hasattr(help_data,"USAGE_VERBS"): sys.stdout.write(help_data.USAGE_VERBS); return 0
    if first=="list-functions":
        if help_data and hasattr(help_data,"LIST_FUNCTIONS"): sys.stdout.write(help_data.LIST_FUNCTIONS); return 0
    if first=="usage-functions":
        if help_data and hasattr(help_data,"USAGE_FUNCTIONS"): sys.stdout.write(help_data.USAGE_FUNCTIONS); return 0
    if first=="list-keywords":
        if help_data and hasattr(help_data,"LIST_KEYWORDS"): sys.stdout.write(help_data.LIST_KEYWORDS); return 0
    if first=="usage-keywords":
        if help_data and hasattr(help_data,"USAGE_KEYWORDS"): sys.stdout.write(help_data.USAGE_KEYWORDS); return 0
    if first=="find":
        needle=" ".join(args[1:]).lower()
        found=[]
        if help_data and hasattr(help_data,"HELP_MAP"):
            for k,v in help_data.HELP_MAP.items():
                if needle in k.lower() or needle in v.lower(): found.append(k)
        for f in found: sys.stdout.write(f+"\n")
        return 0
    # search exact text across verb/function/keyword/flag
    key=" ".join(args)
    txt=get_help_text("verb",key) or get_help_text("function",key) or get_help_text("keyword",key)
    if txt: sys.stdout.write(txt); return 0
    if help_data and hasattr(help_data,"TOPIC_HELP") and key in help_data.TOPIC_HELP:
        sys.stdout.write(help_data.TOPIC_HELP[key]); return 0
    sys.stdout.write(f'No help found for "{key}". Please try \'mlr help find {key}\' for approximate match.\nSee also \'mlr help topics\'.\n')
    return 0

