}
def read_aux_bytes(files):
    data=b""
    if not files:
        return sys.stdin.buffer.read()
    for fn in files:
        try:
            with open(fn,"rb") as fh: data+=fh.read()
        except FileNotFoundError:
            raise MillerError(f"mlr: open {fn}: no such file or directory")
    return data
def run_aux(name, args):
    if name=="aux-list":
        sys.stdout.write("Available entries:\\n  mlr aux-list\\n  mlr hex\\n  mlr lecat\\n  mlr termcvt\\n  mlr unhex\\nFor more information, please invoke mlr {subcommand} --help.\\n"); return 0
    if any(a in ("-h","--help") for a in args):
