        if mlrrc=="__none__":
            return []
        files=[mlrrc]
    else:
        home=os.environ.get("HOME")
        if home:
            hf=os.path.join(home,".mlrrc")
            if os.path.exists(hf): files.append(hf)
        lf=os.path.join(os.getcwd(),".mlrrc")
        if os.path.exists(lf):
            # avoid double if same?
            if not files or os.path.abspath(files[-1])!=os.path.abspath(lf): files.append(lf)
            elif files and os.path.abspath(files[-1])==os.path.abspath(lf):
                # Miller says both processed; if HOME==cwd it's same file processed twice - idempotent; keep one.
