ast_code = '''
def ast_label_children(node):
    if node is None:
        return ('no-op', [])
    k=node.get("kind")
    if k=="program":
        return ('statement block', [ast_label_children(s) for s in node["stmts"]])
    if k=="block":
        return ('statement block', [ast_label_children(s) for s in node["body"]])
    if k=="begin":
        return ('begin block', [ast_label_children({"kind":"block","body":node["body"]})])
    if k=="end":
        return ('end block', [ast_label_children({"kind":"block","body":node["body"]})])
    if k=="funcdef":
        params_node=('parameter list', [(('parameter'), [ (f'parameter name "{p}"', [])]) for p in node["params"]])
        # The above comprehension constructs weird labels - build explicitly
        param_children=[]
        for prm in node["params"]:
            param_children.append(('parameter', [(f'parameter name "{prm}"', [])]))
        label='function definition' if node.get("is_func") else 'subroutine definition'
        return (f'{label} "{node["name"]}"', [('parameter list', param_children), ast_label_children({"kind":"block","body":node["body"]})])
    if k=="if":
        items=[]
        cur=node
        first=True
        while cur is not None and cur.get("kind")=="if":
            item_label='if-item "if"' if first else 'if-item "elif"'
            children=[ast_label_children(cur["cond"]), ast_stmt_block(cur["then"])]
            items.append((item_label, children))
            cur=cur.get("else")
            first=False
        if cur is not None:
            items.append(('if-item "else"', [ast_stmt_block(cur)]))
        return ('if-chain', items)
    if k=="while":
        return ('while loop "while"', [ast_label_children(node["cond"]), ast_stmt_block(node["body"])])
    if k=="dowhile":
        return ('do-while loop "while"', [ast_label_children(node["cond"]), ast_stmt_block(node["body"])])
    if k=="forin":
        label='double-variable for-loop "for"' if len(node["vars"])>=2 else 'single-variable for-loop "for"'
        children=[(f'local variable "{v}"',[]) for v in node["vars"]]
        children.append(ast_label_children(node["expr"])); children.append(ast_stmt_block(node["body"]))
        return (label, children)
    if k=="for":
        children=[]
        if node.get("init") is not None: children.append(ast_label_children(node["init"]))
        if node.get("cond") is not None: children.append(ast_label_children(node["cond"]))
        if node.get("incr") is not None: children.append(ast_label_children(node["incr"]))
        children.append(ast_stmt_block(node["body"]))
        return ('for loop "for"', children)
    if k=="return":
        return ('return "return"', [ast_label_children(node["expr"])] if node.get("expr") is not None else [('no-op',[])])
    if k in ("print","printn","eprint","eprintn","fprint"):
        label_map={"print":'print statement "print"', "printn":'print statement "printn"', "eprint":'eprint statement "eprint"', "eprintn":'eprintn statement "eprintn"', "fprint":'print statement "print"'}
        children=[('function callsite', [ast_label_children(a) for a in node["args"]]), ('no-op',[])]
        return (label_map.get(k,k), children)
    if k=="exprstmt":
        return ast_label_children(node["expr"])
    if k=="callstmt":
        return ast_label_children(node["expr"])
    if k=="unset":
        return ('unset "unset"', [ast_label_children(node["expr"])])
    if k in ("emit","emitf","emit1","emitp"):
        return (f'{k} "{k}"', [ast_label_children(a) for a in node["args"]])
    if k=="break": return ('break "break"', [])
    if k=="continue": return ('continue "continue"', [])
    if k=="decl":
        # declarations as assignments
        children=[]
        for nm,init in node["decls"]:
            children.append(('assignment "="', [(f'local variable "{nm}"',[]), ast_label_children(init) if init else ('no-op',[])]))
        if len(children)==1: return children[0]
        return ('statement block', children)
    if k=="assign":
        target=ast_label_children(node["target"])
        if node["op"]=="=":
            return ('assignment "="', [target, ast_label_children(node["value"])])
        baseop=node["op"][:-1]
        # compound becomes assignment with operator child
        if baseop==".":
            opnode=('dot operator "."', [target, ast_label_children(node["value"])])
        else:
            opnode=(f'operator "{baseop}"', [target, ast_label_children(node["value"])])
        return ('assignment "="', [target, opnode])
    if k=="binary":
        if node["op"]==".":
