        if v.typ=="float": return (f'float literal "{mv_to_string(v)}"', [])
        if v.typ=="string": return (f'string literal "{v.val}"', [])
        if v.typ=="bool": return (f'bool literal "{"true" if v.val else "false"}"', [])
        if v.typ=="null": return ('null literal "null"', [])
        if v.typ=="absent": return ('absent literal "absent"', [])
        if v.typ=="empty": return ('string literal ""', [])
        return (f'{v.typ} literal "{mv_to_string(v)}"', [])
    if k=="array":
        return ('array literal "[]"', [ast_label_children(e) for e in node["elems"]])
