    if k=="srec_index":
        return ('indirect field value "$[]"', [ast_label_children(node["index"])])
    if k=="srec_index2":
        return ('field name from index "$[[]]"', [ast_label_children(node["index"])])
    if k=="postinc":
        return (f'operator "{node["op"]}"', [ast_label_children(node["expr"])])
