        name=label.split('"')[1]; return f"${name}"
    if label.startswith('direct oosvar value'):
        name=label.split('"')[1]; return f"@{name}"
    if label.startswith('local variable'):
        return label.split('"')[1]
    if label.startswith('operator'):
        return label.split('"')[1]
    if label.startswith('dot operator'): return '.'
    if label.startswith('int literal'): return label.split('"')[1]
    if label.startswith('float literal'): return label.split('"')[1]
    if label.startswith('string literal'):
        # label may contain quotes inside; extract between first and last quote
        return '"' + label[len('string literal "'):-1] + '"'
    if label.startswith('bool literal'): return label.split('"')[1]
    if label.startswith('null literal'): return 'null'
    if label.startswith('function callsite'):
        parts=label.split('"')
        return parts[1] if len(parts)>1 and parts[1] else ''
    if label=='function callsite': return ''
    if label.startswith('print statement'): return 'print'
    if label=='no-op': return 'no-op'
    if label.startswith('if-chain'): return 'if-chain'
    if label.startswith('if-item'):
        return label.split('"')[1]
    if label.startswith('while loop'): return 'while'
    if label.startswith('begin block'): return 'begin'
    if label.startswith('end block'): return 'end'
    if label.startswith('full record'): return '$*'
    if label.startswith('full oosvar'): return '@*'
    if label.startswith('array literal'): return 'array-literal'
    if label.startswith('map literal'): return 'map-literal'
    if label.startswith('map-literal key-value pair'): return ':'
    if label.startswith('array or map index access'): return '[]'
    if label.startswith('unset'): return 'unset'
    if label.startswith('return'): return 'return'
    if label.startswith('parameter list'): return 'parameter-list'
    if label.startswith('parameter name'): return label.split('"')[1]
    if label=='parameter': return 'parameter'
    if label.startswith('function definition'):
        parts=label.split('"'); return parts[1] if len(parts)>1 else 'func'
    return label

