def _repl_function_usage(name):
    if help_data is None or not hasattr(help_data,"USAGE_FUNCTIONS"): return None
    text=help_data.USAGE_FUNCTIONS
    # blocks separated by blank lines; find start at line beginning name + space
    for m in re.finditer(r'(?m)^([A-Za-z0-9_!<>+*/%.^&|=-]+)  \\(', text):
        if m.group(1)==name:
            start=m.start()
            nxt=text.find("\\n\\n", start)
            if nxt==-1: return text[start:]
            return text[start:nxt+1]
    return None
def _repl_detail_section(proto):
    if help_data is None or not hasattr(help_data,"REPL_HELP"): return ""
    txt=help_data.REPL_HELP.get("repl-details","")
    # Find a line equal-ish starting with :proto
    lines=txt.splitlines()
    for i,line in enumerate(lines):
        if line.startswith(":"+proto):
            # body starts at next line
            out=[]
            j=i+1
            while j < len(lines):
                if re.match(r'^:[a-z]+ or ', lines[j]) or re.match(r'^:[a-z]+$', lines[j]):
                    break
                out.append(lines[j]); j+=1
            # strip trailing blanks
            while out and out[-1]=="": out.pop()
            return "\\n".join(out)+"\\n"
    return ""

