                            if read_index>=len(input_records) and open_files:
                                # will be at EOF: do_read prints No open files though for until we should break?
                                break
                            if not do_read(): break
                            # session env record updated via set_current
                            try:
                                if eval_until_expr(expr_code): break
                            except MillerError as me: sys.stderr.write(str(me)+"\\n"); break
                else:
                    try: cnt=int(rest.split()[0])
                    except: sys.stdout.write(_repl_detail_section("s or :skip")); continue
                    for _ in range(cnt):
                        if read_index>=len(input_records):
                            if open_files: sys.stdout.write("End of record stream\\n")
                            break
                        if not do_read(): break
            elif cmd=="process":
                if not rest: sys.stdout.write(_repl_detail_section("p or :process")); continue
                def process_one():
                    # main on current, then write if included
                    session_env.include_record=True
                    for stmt in list(proc.main_stmts):
                        try: proc.exec_stmt(stmt, session_env)
                        except MillerError as me: sys.stderr.write(str(me)+"\\n")
                    handle_out_items()
                    if getattr(session_env,'include_record',True): sink.write_record(current.clone())
                    sink.flush()
                if rest.startswith("until ") or rest.startswith("u "):
                    expr_code=rest[6:].strip() if rest.startswith("until ") else rest[2:].strip()
                    while True:
                        if not do_read(): break
                        process_one()
                        if expr_code!="intr":
                            try:
                                if eval_until_expr(expr_code): break
                            except: break
                else:
                    try: cnt=int(rest.split()[0])
                    except: sys.stdout.write(_repl_detail_section("p or :process")); continue
                    for _ in range(cnt):
                        if not do_read(): break
                        process_one()
            elif cmd=="begin": execute_begin_end("begin")
            elif cmd=="main":
                session_env.include_record=True
                execute_statements(list(proc.main_stmts), session_env, immediate=False)
            elif cmd=="end": execute_begin_end("end")
            elif cmd=="astprint":
                if rest in ("none",""): ast_mode=None
                elif rest=="parex": ast_mode="parex"
                elif rest=="parex1": ast_mode="parex1"
                elif rest=="indent": ast_mode="indent"
                else: ast_mode=rest
            elif cmd=="blocks":
                sys.stdout.write(f"#begin {len(proc.begin_bodies)}\\n#main  {len(proc.main_stmts)}\\n#end   {len(proc.end_bodies)}\\n")
            elif cmd=="resetblocks":
                if rest=="begin": proc.begin_bodies=[]
                elif rest=="main": proc.main_stmts=[]
                elif rest=="end": proc.end_bodies=[]
                elif rest=="": proc.begin_bodies=[]; proc.main_stmts=[]; proc.end_bodies=[]
                else: proc.begin_bodies=[]; proc.main_stmts=[]; proc.end_bodies=[]
            elif cmd in (">",):
                pass
            else:
                # :> and :>> are their own commands (rest is filename in parts)
                sys.stdout.write(f"Unknown REPL command :{cmdname}\\n")
            continue
        if stripped.startswith(">") or False:
            pass
        # Handle :> / :>> written as stripped starting with ':' already handled above as cmdname '>' - need intercept before generic colon handling.
        # DSL line
        stmts=parse_and_classify(stripped)
        if stmts is None: continue
        if ast_mode: _repl_print_ast(stmts, ast_mode)
        if warn_mode:
            # use a temporary processor warnings? skip detailed
            pass
        execute_statements(stmts, session_env, immediate=True)
    sink.close()
    return 0

def _repl_print_ast(stmts, mode):
    tree=('statement block', [ast_label_children(s) for s in stmts])
    if mode=="indent": sys.stdout.write("AST:\\n"+"\\n".join(render_ast_p(tree))+"\\n\\n")
    elif mode=="parex": sys.stdout.write("\\n".join(render_ast_d_from_tree(tree,0))+"\\n\\n")
    elif mode=="parex1": sys.stdout.write(render_ast_d_tree_oneline(tree)+"\\n\\n")
